def jira_get_user_profile(workspace_id, connection_id, account_id=None, user_key=None, username=None, refresh=None, **_extra):
    import json, os, datetime, time, re, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0275000" if __import__("os").path.isdir("./environment_mix/0275000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Prepare request log row early; finalize before returning.
    tool_requests = _load("tool_requests.json")
    req_id = "ais_trq_" + uuid.uuid4().hex[:26]
    req_row = {
        "tool_request_id": req_id,
        "workspace_id": workspace_id,
        "connection_id": connection_id,
        "tool_name": "jira_get_user_profile",
        "params_json": {
            "account_id": account_id,
            "user_key": user_key,
            "username": username,
            "refresh": bool(refresh) if refresh is not None else False,
        },
        "status": "received",
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "result_json": None,
        "affected_entities": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now,
    }
    tool_requests.append(req_row)
    _save("tool_requests.json", tool_requests)

    def _finalize(status, http_status=None, error_code=None, error_message=None, result_json=None, affected=None):
        finished = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        req_row["status"] = status
        req_row["http_status"] = http_status
        req_row["error_code"] = error_code
        req_row["error_message"] = error_message
        req_row["result_json"] = result_json
        req_row["affected_entities"] = affected
        if req_row["started_at"] is None:
            req_row["started_at"] = finished
        req_row["finished_at"] = finished
        req_row["updated_at"] = finished
        _save("tool_requests.json", tool_requests)

    # Input validation
    if not isinstance(workspace_id, str) or not workspace_id:
        _finalize("failed", http_status=400, error_code="VALIDATION_ERROR", error_message="workspace_id must be a non-empty string")
        return _err("VALIDATION_ERROR", "workspace_id must be a non-empty string")
    if not isinstance(connection_id, str) or not connection_id:
        _finalize("failed", http_status=400, error_code="VALIDATION_ERROR", error_message="connection_id must be a non-empty string")
        return _err("VALIDATION_ERROR", "connection_id must be a non-empty string")

    selectors = [account_id is not None, user_key is not None, username is not None]
    if sum(1 for x in selectors if x) != 1:
        _finalize("failed", http_status=400, error_code="VALIDATION_ERROR", error_message="Provide exactly one of account_id, user_key, or username")
        return _err("VALIDATION_ERROR", "Provide exactly one of account_id, user_key, or username")
    for nm, v in (("account_id", account_id), ("user_key", user_key), ("username", username)):
        if v is not None and (not isinstance(v, str) or not v.strip()):
            _finalize("failed", http_status=400, error_code="VALIDATION_ERROR", error_message=f"{nm} must be a non-empty string when provided")
            return _err("VALIDATION_ERROR", f"{nm} must be a non-empty string when provided")
    if refresh is not None and not isinstance(refresh, bool):
        _finalize("failed", http_status=400, error_code="VALIDATION_ERROR", error_message="refresh must be boolean when provided")
        return _err("VALIDATION_ERROR", "refresh must be boolean when provided")

    # Resolve workspace and connection
    workspaces = _load("workspaces.json")
    ws = next((w for w in workspaces if w.get("workspace_id") == workspace_id), None)
    if not ws:
        _finalize("failed", http_status=404, error_code="NOT_FOUND", error_message="Workspace not found")
        return _err("NOT_FOUND", "Workspace not found")
    if ws.get("status") != "active":
        _finalize("rejected", http_status=403, error_code="WORKSPACE_INACTIVE", error_message="Workspace is not active")
        return _err("UNAUTHORIZED", "Workspace is not active", error_code="WORKSPACE_INACTIVE")
    conns = _load("atlassian_connections.json")
    conn = next((c for c in conns if c.get("connection_id") == connection_id and c.get("workspace_id") == workspace_id), None)
    if not conn:
        _finalize("failed", http_status=404, error_code="NOT_FOUND", error_message="Connection not found for workspace")
        return _err("NOT_FOUND", "Connection not found for workspace")
    if conn.get("product") != "jira":
        _finalize("failed", http_status=400, error_code="VALIDATION_ERROR", error_message="connection_id must refer to a Jira connection")
        return _err("VALIDATION_ERROR", "connection_id must refer to a Jira connection")
    if conn.get("status") != "active":
        _finalize("failed", http_status=503, error_code="UPSTREAM_UNAVAILABLE", error_message="Jira connection is not active")
        return _err("CONFLICT", "Jira connection is not active", error_code="UPSTREAM_UNAVAILABLE")

    # Start execution
    started = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    req_row["status"] = "running"
    req_row["started_at"] = started
    req_row["updated_at"] = started
    _save("tool_requests.json", tool_requests)

    # Find cached user entity
    jira_entities = _load("jira_entities.json")

    def _matches_user(ent):
        if ent.get("workspace_id") != workspace_id or ent.get("connection_id") != connection_id: return False
        if ent.get("entity_type") != "user": return False
        if ent.get("status") not in ("active", "deleted", "tombstoned"): return False
        payload = ent.get("json_payload") if isinstance(ent.get("json_payload"), dict) else {}
        if account_id is not None:
            return ent.get("external_id") == account_id or payload.get("accountId") == account_id
        if user_key is not None:
            return ent.get("external_id") == user_key or payload.get("key") == user_key or payload.get("userKey") == user_key
        return ent.get("external_id") == username or payload.get("name") == username or payload.get("username") == username

    user_ent = next((e for e in jira_entities if _matches_user(e)), None)

    # "Refresh" behavior: offline server can't fetch upstream; treat refresh as touching fetched_at if entity exists
    if refresh:
        if not user_ent:
            req_row["status"] = "failed"
            _finalize("failed", http_status=404, error_code="NOT_FOUND", error_message="User not found in cache; upstream fetch unavailable offline")
            return _err("NOT_FOUND", "User not found in cache; upstream fetch unavailable offline")
        user_ent["fetched_at"] = now
        user_ent["updated_at"] = now
        _save("jira_entities.json", jira_entities)

    if not user_ent:
        _finalize("failed", http_status=404, error_code="NOT_FOUND", error_message="User not found")
        return _err("NOT_FOUND", "User not found")

    result = user_ent.get("json_payload")
    affected = [{"system": "jira", "entity_type": "user", "external_id": user_ent.get("external_id")}]
    _finalize("succeeded", http_status=200, result_json=result, affected=affected)

    return {
        "data": result,
        "meta": {
            "tool_request_id": req_id,
            "workspace_id": workspace_id,
            "connection_id": connection_id,
            "latency_ms": int((time.time() - t0) * 1000),
        },
    }

def jira_get_issue(workspace_id, connection_id, issue_key, fields=None, expand=None, comment_limit=None, refresh=None, **_extra):
    import json, os, datetime, time, uuid, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0275000" if __import__("os").path.isdir("./environment_mix/0275000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    tool_requests = _load("tool_requests.json")
    req_id = "ais_trq_" + uuid.uuid4().hex[:26]
    params_norm = {
        "issue_key": issue_key,
        "fields": fields,
        "expand": expand,
        "comment_limit": comment_limit,
        "refresh": bool(refresh) if refresh is not None else False,
    }
    req_row = {
        "tool_request_id": req_id,
        "workspace_id": workspace_id,
        "connection_id": connection_id,
        "tool_name": "jira_get_issue",
        "params_json": params_norm,
        "status": "received",
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "result_json": None,
        "affected_entities": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now,
    }
    tool_requests.append(req_row)
    _save("tool_requests.json", tool_requests)

    def _finalize(status, http_status=None, error_code=None, error_message=None, result_json=None, affected=None):
        finished = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        req_row["status"] = status
        req_row["http_status"] = http_status
        req_row["error_code"] = error_code
        req_row["error_message"] = error_message
        req_row["result_json"] = result_json
        req_row["affected_entities"] = affected
        if req_row["started_at"] is None:
            req_row["started_at"] = finished
        req_row["finished_at"] = finished
        req_row["updated_at"] = finished
        _save("tool_requests.json", tool_requests)

    # Validate inputs
    if not isinstance(workspace_id, str) or not workspace_id:
        _finalize("failed", http_status=400, error_code="VALIDATION_ERROR", error_message="workspace_id must be a non-empty string")
        return _err("VALIDATION_ERROR", "workspace_id must be a non-empty string")
    if not isinstance(connection_id, str) or not connection_id:
        _finalize("failed", http_status=400, error_code="VALIDATION_ERROR", error_message="connection_id must be a non-empty string")
        return _err("VALIDATION_ERROR", "connection_id must be a non-empty string")
    if not isinstance(issue_key, str) or not issue_key.strip():
        _finalize("failed", http_status=400, error_code="VALIDATION_ERROR", error_message="issue_key must be a non-empty string")
        return _err("VALIDATION_ERROR", "issue_key must be a non-empty string")
    if fields is not None and not (isinstance(fields, str) or (isinstance(fields, list) and all(isinstance(x, str) for x in fields))):
        _finalize("failed", http_status=400, error_code="VALIDATION_ERROR", error_message="fields must be a string or list of strings")
        return _err("VALIDATION_ERROR", "fields must be a string or list of strings")
    if expand is not None and not isinstance(expand, str):
        _finalize("failed", http_status=400, error_code="VALIDATION_ERROR", error_message="expand must be a string when provided")
        return _err("VALIDATION_ERROR", "expand must be a string when provided")
    if comment_limit is not None:
        if not isinstance(comment_limit, int) or comment_limit < 0:
            _finalize("failed", http_status=400, error_code="VALIDATION_ERROR", error_message="comment_limit must be an integer >= 0")
            return _err("VALIDATION_ERROR", "comment_limit must be an integer >= 0")
    if refresh is not None and not isinstance(refresh, bool):
        _finalize("failed", http_status=400, error_code="VALIDATION_ERROR", error_message="refresh must be boolean when provided")
        return _err("VALIDATION_ERROR", "refresh must be boolean when provided")

    workspaces = _load("workspaces.json")
    ws = next((w for w in workspaces if w.get("workspace_id") == workspace_id), None)
    if not ws:
        _finalize("failed", http_status=404, error_code="NOT_FOUND", error_message="Workspace not found")
        return _err("NOT_FOUND", "Workspace not found")
    if ws.get("status") != "active":
        _finalize("rejected", http_status=403, error_code="WORKSPACE_INACTIVE", error_message="Workspace is not active")
        return _err("UNAUTHORIZED", "Workspace is not active", error_code="WORKSPACE_INACTIVE")

    conns = _load("atlassian_connections.json")
    conn = next((c for c in conns if c.get("connection_id") == connection_id and c.get("workspace_id") == workspace_id), None)
    if not conn:
        _finalize("failed", http_status=404, error_code="NOT_FOUND", error_message="Connection not found for workspace")
        return _err("NOT_FOUND", "Connection not found for workspace")
    if conn.get("product") != "jira":
        _finalize("failed", http_status=400, error_code="VALIDATION_ERROR", error_message="connection_id must refer to a Jira connection")
        return _err("VALIDATION_ERROR", "connection_id must refer to a Jira connection")
    if conn.get("status") != "active":
        _finalize("failed", http_status=503, error_code="UPSTREAM_UNAVAILABLE", error_message="Jira connection is not active")
        return _err("CONFLICT", "Jira connection is not active", error_code="UPSTREAM_UNAVAILABLE")

    started = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    req_row["status"] = "running"
    req_row["started_at"] = started
    req_row["updated_at"] = started
    _save("tool_requests.json", tool_requests)

    jira_entities = _load("jira_entities.json")
    issue_ent = next(
        (e for e in jira_entities
         if e.get("workspace_id") == workspace_id
         and e.get("connection_id") == connection_id
         and e.get("entity_type") == "issue"
         and e.get("external_key") == issue_key),
        None
    )

    # Offline "refresh": only possible if entity exists; touch fetched_at and updated_at
    if refresh:
        if not issue_ent:
            _finalize("failed", http_status=404, error_code="NOT_FOUND", error_message="Issue not found in cache; upstream fetch unavailable offline")
            return _err("NOT_FOUND", "Issue not found in cache; upstream fetch unavailable offline")
        issue_ent["fetched_at"] = now
        issue_ent["updated_at"] = now
        _save("jira_entities.json", jira_entities)

    if not issue_ent:
        _finalize("failed", http_status=404, error_code="NOT_FOUND", error_message="Issue not found")
        return _err("NOT_FOUND", "Issue not found")

    payload = issue_ent.get("json_payload") if isinstance(issue_ent.get("json_payload"), dict) else {}
    # Apply fields filtering at a shallow level when possible
    if fields is None:
        filtered = payload
    else:
        # Normalize fields list
        if isinstance(fields, str):
            fstr = fields.strip()
            if fstr == "*all":
                filtered = payload
            else:
                flist = [x.strip() for x in fstr.split(",") if x.strip()]
                flist = flist or []
                filtered = {}
                for k in ("id", "key", "self"):
                    if k in payload:
                        filtered[k] = payload.get(k)
                if "fields" in payload and isinstance(payload.get("fields"), dict):
                    filtered_fields = {}
                    for fn in flist:
                        if fn in payload["fields"]:
                            filtered_fields[fn] = payload["fields"][fn]
                    filtered["fields"] = filtered_fields
                else:
                    if flist and any(fn in payload for fn in flist):
                        for fn in flist:
                            if fn in payload:
                                filtered[fn] = payload[fn]
        else:
            flist = [x.strip() for x in fields if isinstance(x, str) and x.strip()]
            filtered = {}
            for k in ("id", "key", "self"):
                if k in payload:
                    filtered[k] = payload.get(k)
            if "fields" in payload and isinstance(payload.get("fields"), dict):
                filtered_fields = {}
                for fn in flist:
                    if fn in payload["fields"]:
                        filtered_fields[fn] = payload["fields"][fn]
                filtered["fields"] = filtered_fields

    # comment_limit: if comments are present in fields/comment container, trim
    if comment_limit is not None and isinstance(filtered, dict):
        fld = filtered.get("fields")
        if isinstance(fld, dict):
            comment_obj = fld.get("comment")
            if isinstance(comment_obj, dict) and isinstance(comment_obj.get("comments"), list):
                comment_obj = dict(comment_obj)
                comment_obj["comments"] = comment_obj.get("comments", [])[:comment_limit]
                fld = dict(fld)
                fld["comment"] = comment_obj
                filtered["fields"] = fld

    affected = [{"system": "jira", "entity_type": "issue", "external_id": issue_ent.get("external_id")}]
    _finalize("succeeded", http_status=200, result_json=filtered, affected=affected)

    return {
        "data": filtered,
        "meta": {
            "tool_request_id": req_id,
            "workspace_id": workspace_id,
            "connection_id": connection_id,
            "latency_ms": int((time.time() - t0) * 1000),
        },
    }

def jira_search(workspace_id, connection_id, jql, fields=None, limit=None, start_at=None, projects_filter=None, expand=None, refresh=None, **_extra):
    import json, os, datetime, time, uuid, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0275000" if __import__("os").path.isdir("./environment_mix/0275000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Resolve workspace early for pagination defaults
    workspaces = _load("workspaces.json")
    ws = next((w for w in workspaces if w.get("workspace_id") == workspace_id), None)

    # Prepare request log
    tool_requests = _load("tool_requests.json")
    req_id = "ais_trq_" + uuid.uuid4().hex[:26]
    params_norm = {
        "jql": jql,
        "fields": fields,
        "expand": expand,
        "start_at": start_at,
        "limit": limit,
        "projects_filter": projects_filter,
        "refresh": bool(refresh) if refresh is not None else False,
    }
    req_row = {
        "tool_request_id": req_id,
        "workspace_id": workspace_id,
        "connection_id": connection_id,
        "tool_name": "jira_search",
        "params_json": params_norm,
        "status": "received",
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "result_json": None,
        "affected_entities": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now,
    }
    tool_requests.append(req_row)
    _save("tool_requests.json", tool_requests)

    def _finalize(status, http_status=None, error_code=None, error_message=None, result_json=None, affected=None):
        finished = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        req_row["status"] = status
        req_row["http_status"] = http_status
        req_row["error_code"] = error_code
        req_row["error_message"] = error_message
        req_row["result_json"] = result_json
        req_row["affected_entities"] = affected
        if req_row["started_at"] is None:
            req_row["started_at"] = finished
        req_row["finished_at"] = finished
        req_row["updated_at"] = finished
        _save("tool_requests.json", tool_requests)

    # Validate inputs
    if not isinstance(workspace_id, str) or not workspace_id:
        _finalize("failed", http_status=400, error_code="VALIDATION_ERROR", error_message="workspace_id must be a non-empty string")
        return _err("VALIDATION_ERROR", "workspace_id must be a non-empty string")
    if not isinstance(connection_id, str) or not connection_id:
        _finalize("failed", http_status=400, error_code="VALIDATION_ERROR", error_message="connection_id must be a non-empty string")
        return _err("VALIDATION_ERROR", "connection_id must be a non-empty string")
    if not isinstance(jql, str) or not jql.strip():
        _finalize("failed", http_status=400, error_code="VALIDATION_ERROR", error_message="jql must be a non-empty string")
        return _err("VALIDATION_ERROR", "jql must be a non-empty string")
    if fields is not None and not isinstance(fields, str):
        _finalize("failed", http_status=400, error_code="VALIDATION_ERROR", error_message="fields must be a string when provided")
        return _err("VALIDATION_ERROR", "fields must be a string when provided")
    if expand is not None and not isinstance(expand, str):
        _finalize("failed", http_status=400, error_code="VALIDATION_ERROR", error_message="expand must be a string when provided")
        return _err("VALIDATION_ERROR", "expand must be a string when provided")
    if projects_filter is not None and not isinstance(projects_filter, str):
        _finalize("failed", http_status=400, error_code="VALIDATION_ERROR", error_message="projects_filter must be a string when provided")
        return _err("VALIDATION_ERROR", "projects_filter must be a string when provided")
    if refresh is not None and not isinstance(refresh, bool):
        _finalize("failed", http_status=400, error_code="VALIDATION_ERROR", error_message="refresh must be boolean when provided")
        return _err("VALIDATION_ERROR", "refresh must be boolean when provided")

    if not ws:
        _finalize("failed", http_status=404, error_code="NOT_FOUND", error_message="Workspace not found")
        return _err("NOT_FOUND", "Workspace not found")
    if ws.get("status") != "active":
        _finalize("rejected", http_status=403, error_code="WORKSPACE_INACTIVE", error_message="Workspace is not active")
        return _err("UNAUTHORIZED", "Workspace is not active", error_code="WORKSPACE_INACTIVE")

    # Pagination enforcement
    default_page = ws.get("default_page_size")
    max_page = ws.get("max_page_size")
    if not isinstance(default_page, int) or default_page < 1:
        default_page = 25
    if not isinstance(max_page, int) or max_page < 1:
        max_page = 200

    if start_at is None:
        start_at = 0
    if not isinstance(start_at, int) or start_at < 0:
        _finalize("failed", http_status=400, error_code="VALIDATION_ERROR", error_message="start_at must be an integer >= 0")
        return _err("VALIDATION_ERROR", "start_at must be an integer >= 0")

    if limit is None:
        limit = default_page
    if not isinstance(limit, int):
        _finalize("failed", http_status=400, error_code="VALIDATION_ERROR", error_message="limit must be an integer")
        return _err("VALIDATION_ERROR", "limit must be an integer")
    if limit < 1 or limit > max_page:
        _finalize("failed", http_status=400, error_code="VALIDATION_ERROR", error_message=f"limit must be between 1 and {max_page}")
        return _err("VALIDATION_ERROR", f"limit must be between 1 and {max_page}")

    # Resolve connection
    conns = _load("atlassian_connections.json")
    conn = next((c for c in conns if c.get("connection_id") == connection_id and c.get("workspace_id") == workspace_id), None)
    if not conn:
        _finalize("failed", http_status=404, error_code="NOT_FOUND", error_message="Connection not found for workspace")
        return _err("NOT_FOUND", "Connection not found for workspace")
    if conn.get("product") != "jira":
        _finalize("failed", http_status=400, error_code="VALIDATION_ERROR", error_message="connection_id must refer to a Jira connection")
        return _err("VALIDATION_ERROR", "connection_id must refer to a Jira connection")
    if conn.get("status") != "active":
        _finalize("failed", http_status=503, error_code="UPSTREAM_UNAVAILABLE", error_message="Jira connection is not active")
        return _err("CONFLICT", "Jira connection is not active", error_code="UPSTREAM_UNAVAILABLE")

    started = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    req_row["status"] = "running"
    req_row["started_at"] = started
    req_row["updated_at"] = started
    _save("tool_requests.json", tool_requests)

    jira_entities = _load("jira_entities.json")

    # Very lightweight offline "JQL": keyword match against external_key/title/indexed_text,
    # and optional projects_filter by issue key prefix.
    keyword = jql.strip()
    pf = None
    if projects_filter:
        pf = [x.strip() for x in projects_filter.split(",") if x.strip()]
        pf = [p.upper() for p in pf if p]

    issues = []
    for e in jira_entities:
        if e.get("workspace_id") != workspace_id or e.get("connection_id") != connection_id: 
            continue
        if e.get("entity_type") != "issue":
            continue
        if e.get("status") != "active":
            continue
        ek = (e.get("external_key") or "").upper()
        if pf:
            # project key is substring before '-'
            proj = ek.split("-", 1)[0] if "-" in ek else ""
            if proj not in pf:
                continue
        hay = " ".join([
            (e.get("external_key") or ""),
            (e.get("title") or ""),
            (e.get("indexed_text") or ""),
        ]).lower()
        if keyword.lower() in hay:
            issues.append(e)

    # Deterministic sort: by external_key then id
    issues.sort(key=lambda x: ((x.get("external_key") or ""), (x.get("jira_entity_id") or "")))

    total = len(issues)
    page = issues[start_at:start_at + limit]
    has_more = (start_at + limit) < total
    next_cursor = (start_at + limit) if has_more else None

    # Refresh behavior offline: touch fetched_at for returned entities if refresh requested
    affected = []
    if refresh:
        changed = False
        for ent in page:
            ent["fetched_at"] = now
            ent["updated_at"] = now
            changed = True
        if changed:
            _save("jira_entities.json", jira_entities)

    # Build search response: mimic Jira search envelope minimally
    def _select_issue_payload(ent):
        p = ent.get("json_payload") if isinstance(ent.get("json_payload"), dict) else {}
        if not fields:
            return p
        # if comma-separated field list, reduce payload["fields"] when present
        flist = [x.strip() for x in fields.split(",") if x.strip()]
        if not flist:
            return p
        out = {}
        for k in ("id", "key", "self"):
            if k in p:
                out[k] = p.get(k)
        if "fields" in p and isinstance(p.get("fields"), dict):
            out_fields = {}
            for fn in flist:
                if fn in p["fields"]:
                    out_fields[fn] = p["fields"][fn]
            out["fields"] = out_fields
        return out

    issues_payload = []
    for ent in page:
        issues_payload.append(_select_issue_payload(ent))
        affected.append({"system": "jira", "entity_type": "issue", "external_id": ent.get("external_id")})

    result = {
        "startAt": start_at,
        "maxResults": limit,
        "total": total,
        "issues": issues_payload,
        "isLast": not has_more,
    }

    _finalize("succeeded", http_status=200, result_json=result, affected=affected)

    return {
        "data": result,
        "meta": {
            "tool_request_id": req_id,
            "workspace_id": workspace_id,
            "connection_id": connection_id,
            "latency_ms": int((time.time() - t0) * 1000),
            "has_more": has_more,
            "next_cursor": next_cursor,
        },
    }

def jira_search_fields(workspace_id, connection_id, keyword, limit=None, refresh=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0275000" if __import__("os").path.isdir("./environment_mix/0275000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    workspaces = _load("workspaces.json")
    ws = next((w for w in workspaces if w.get("workspace_id") == workspace_id), None)

    tool_requests = _load("tool_requests.json")
    req_id = "ais_trq_" + uuid.uuid4().hex[:26]
    req_row = {
        "tool_request_id": req_id,
        "workspace_id": workspace_id,
        "connection_id": connection_id,
        "tool_name": "jira_search_fields",
        "params_json": {
            "keyword": keyword,
            "limit": limit,
            "refresh": bool(refresh) if refresh is not None else False,
        },
        "status": "received",
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "result_json": None,
        "affected_entities": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now,
    }
    tool_requests.append(req_row)
    _save("tool_requests.json", tool_requests)

    def _finalize(status, http_status=None, error_code=None, error_message=None, result_json=None, affected=None):
        finished = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        req_row["status"] = status
        req_row["http_status"] = http_status
        req_row["error_code"] = error_code
        req_row["error_message"] = error_message
        req_row["result_json"] = result_json
        req_row["affected_entities"] = affected
        if req_row["started_at"] is None:
            req_row["started_at"] = finished
        req_row["finished_at"] = finished
        req_row["updated_at"] = finished
        _save("tool_requests.json", tool_requests)

    # Validate inputs
    if not isinstance(workspace_id, str) or not workspace_id:
        _finalize("failed", http_status=400, error_code="VALIDATION_ERROR", error_message="workspace_id must be a non-empty string")
        return _err("VALIDATION_ERROR", "workspace_id must be a non-empty string")
    if not isinstance(connection_id, str) or not connection_id:
        _finalize("failed", http_status=400, error_code="VALIDATION_ERROR", error_message="connection_id must be a non-empty string")
        return _err("VALIDATION_ERROR", "connection_id must be a non-empty string")
    if not isinstance(keyword, str) or not keyword.strip():
        _finalize("failed", http_status=400, error_code="VALIDATION_ERROR", error_message="keyword must be a non-empty string")
        return _err("VALIDATION_ERROR", "keyword must be a non-empty string")
    if refresh is not None and not isinstance(refresh, bool):
        _finalize("failed", http_status=400, error_code="VALIDATION_ERROR", error_message="refresh must be boolean when provided")
        return _err("VALIDATION_ERROR", "refresh must be boolean when provided")

    if not ws:
        _finalize("failed", http_status=404, error_code="NOT_FOUND", error_message="Workspace not found")
        return _err("NOT_FOUND", "Workspace not found")
    if ws.get("status") != "active":
        _finalize("rejected", http_status=403, error_code="WORKSPACE_INACTIVE", error_message="Workspace is not active")
        return _err("UNAUTHORIZED", "Workspace is not active", error_code="WORKSPACE_INACTIVE")

    default_page = ws.get("default_page_size")
    max_page = ws.get("max_page_size")
    if not isinstance(default_page, int) or default_page < 1:
        default_page = 25
    if not isinstance(max_page, int) or max_page < 1:
        max_page = 200

    if limit is None:
        limit = default_page
    if not isinstance(limit, int) or limit < 1 or limit > max_page:
        _finalize("failed", http_status=400, error_code="VALIDATION_ERROR", error_message=f"limit must be an integer between 1 and {max_page}")
        return _err("VALIDATION_ERROR", f"limit must be an integer between 1 and {max_page}")

    # Resolve connection
    conns = _load("atlassian_connections.json")
    conn = next((c for c in conns if c.get("connection_id") == connection_id and c.get("workspace_id") == workspace_id), None)
    if not conn:
        _finalize("failed", http_status=404, error_code="NOT_FOUND", error_message="Connection not found for workspace")
        return _err("NOT_FOUND", "Connection not found for workspace")
    if conn.get("product") != "jira":
        _finalize("failed", http_status=400, error_code="VALIDATION_ERROR", error_message="connection_id must refer to a Jira connection")
        return _err("VALIDATION_ERROR", "connection_id must refer to a Jira connection")
    if conn.get("status") != "active":
        _finalize("failed", http_status=503, error_code="UPSTREAM_UNAVAILABLE", error_message="Jira connection is not active")
        return _err("CONFLICT", "Jira connection is not active", error_code="UPSTREAM_UNAVAILABLE")

    started = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    req_row["status"] = "running"
    req_row["started_at"] = started
    req_row["updated_at"] = started
    _save("tool_requests.json", tool_requests)

    jira_entities = _load("jira_entities.json")

    # refresh=true: offline cannot fetch; record request but do not fabricate data.
    if refresh:
        # Touch updated_at on any "project" entities as a weak proxy for refresh that "updated cache entries"
        changed = False
        for e in jira_entities:
            if e.get("workspace_id") == workspace_id and e.get("connection_id") == connection_id and e.get("entity_type") in ("project", "issue"):
                # business rule suggests field metadata is embedded; we cannot re-fetch, but we can mark attempted refresh
                e["updated_at"] = now
                changed = True
        if changed:
            _save("jira_entities.json", jira_entities)

    # Extract field definitions from cached issues/projects payloads
    kw = keyword.strip().lower()
    seen = {}
    matches = []

    def _consider_field(field_id, field_obj, src_entity):
        if not field_id:
            return
        name = None
        schema = None
        if isinstance(field_obj, dict):
            name = field_obj.get("name") or field_obj.get("label") or field_obj.get("id")
            schema = field_obj.get("schema") if isinstance(field_obj.get("schema"), dict) else None
        if not name and isinstance(field_id, str):
            name = field_id
        hay = f"{field_id} {name or ''}".lower()
        if kw not in hay:
            return
        if field_id in seen:
            return
        seen[field_id] = True
        out = {"id": field_id, "name": name}
        if schema is not None:
            out["schema"] = schema
        # include minimal provenance
        out["source"] = {"jira_entity_id": src_entity.get("jira_entity_id"), "entity_type": src_entity.get("entity_type")}
        matches.append(out)

    for e in jira_entities:
        if e.get("workspace_id") != workspace_id or e.get("connection_id") != connection_id:
            continue
        if e.get("entity_type") not in ("issue", "project"):
            continue
        payload = e.get("json_payload")
        if not isinstance(payload, dict):
            continue

        # Common Jira issue payload: payload["fields"] keys are field ids; values are field values (not definitions)
        # But some integrations embed "names"/"schema" maps; attempt to read them if present.
        names = payload.get("names") if isinstance(payload.get("names"), dict) else None
        schema_map = payload.get("schema") if isinstance(payload.get("schema"), dict) else None

        if names:
            for fid, fname in names.items():
                fobj = {"name": fname}
                if schema_map and fid in schema_map and isinstance(schema_map[fid], dict):
                    fobj["schema"] = schema_map[fid]
                _consider_field(fid, fobj, e)

    # Sort by name then id; apply limit
    matches.sort(key=lambda x: (((x.get("name") or "")).lower(), (x.get("id") or "")))
    matches = matches[:limit]

    affected = []
    _finalize("succeeded", http_status=200, result_json=matches, affected=affected)

    return {
        "data": matches,
        "meta": {
            "tool_request_id": req_id,
            "workspace_id": workspace_id,
            "connection_id": connection_id,
            "latency_ms": int((time.time() - t0) * 1000),
            "count": len(matches),
        },
    }

def jira_get_project_issues(workspace_id, connection_id, project_key, limit=None, start_at=None, fields=None, expand=None, refresh=None, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0275000" if __import__("os").path.isdir("./environment_mix/0275000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        import random, string
        return f"{prefix}_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{''.join(random.choice(string.ascii_lowercase+string.digits) for _ in range(10))}"

    def _log_request(status, http_status=None, error_code=None, error_message=None, result_json=None, affected_entities=None):
        tool_requests = _load("tool_requests.json")
        tr_id = _new_id("ais_trq")
        row = {
            "tool_request_id": tr_id,
            "workspace_id": workspace_id,
            "connection_id": connection_id,
            "tool_name": "jira_get_project_issues",
            "params_json": {
                "project_key": project_key,
                "start_at": start_at if start_at is not None else 0,
                "limit": limit,
                "fields": fields,
                "expand": expand,
                "refresh": bool(refresh) if refresh is not None else False
            },
            "status": status,
            "http_status": http_status,
            "error_code": error_code,
            "error_message": error_message,
            "result_json": result_json,
            "affected_entities": affected_entities,
            "started_at": now,
            "finished_at": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
            "created_at": now,
            "updated_at": now
        }
        tool_requests.append(row)
        _save("tool_requests.json", tool_requests)
        return row

    # Validate inputs
    if not isinstance(workspace_id, str) or not workspace_id:
        _log_request("rejected", 400, "VALIDATION_ERROR", "workspace_id must be a non-empty string")
        return _err("VALIDATION_ERROR", "workspace_id must be a non-empty string")
    if not isinstance(connection_id, str) or not connection_id:
        _log_request("rejected", 400, "VALIDATION_ERROR", "connection_id must be a non-empty string")
        return _err("VALIDATION_ERROR", "connection_id must be a non-empty string")
    if not isinstance(project_key, str) or not project_key or not re.match(r"^[A-Z][A-Z0-9_]+$", project_key):
        _log_request("rejected", 400, "VALIDATION_ERROR", "project_key must look like a Jira project key (e.g., PROJ)")
        return _err("VALIDATION_ERROR", "project_key must look like a Jira project key (e.g., PROJ)")
    if limit is not None and (not isinstance(limit, int) or limit < 1):
        _log_request("rejected", 400, "VALIDATION_ERROR", "limit must be an integer >= 1")
        return _err("VALIDATION_ERROR", "limit must be an integer >= 1")
    if start_at is not None and (not isinstance(start_at, int) or start_at < 0):
        _log_request("rejected", 400, "VALIDATION_ERROR", "start_at must be an integer >= 0")
        return _err("VALIDATION_ERROR", "start_at must be an integer >= 0")
    if fields is not None and not isinstance(fields, str):
        _log_request("rejected", 400, "VALIDATION_ERROR", "fields must be a string when provided")
        return _err("VALIDATION_ERROR", "fields must be a string when provided")
    if expand is not None and not isinstance(expand, str):
        _log_request("rejected", 400, "VALIDATION_ERROR", "expand must be a string when provided")
        return _err("VALIDATION_ERROR", "expand must be a string when provided")
    if refresh is not None and not isinstance(refresh, bool):
        _log_request("rejected", 400, "VALIDATION_ERROR", "refresh must be a boolean when provided")
        return _err("VALIDATION_ERROR", "refresh must be a boolean when provided")

    workspaces = _load("workspaces.json")
    ws = next((w for w in workspaces if w.get("workspace_id") == workspace_id), None)
    if not ws:
        _log_request("failed", 404, "NOT_FOUND", "workspace not found")
        return _err("NOT_FOUND", "workspace not found")
    if ws.get("status") != "active":
        _log_request("rejected", 403, "WORKSPACE_INACTIVE", "workspace is not active")
        return _err("UNAUTHORIZED", "workspace is not active", error_code="WORKSPACE_INACTIVE")
    default_page_size = ws.get("default_page_size", 25)
    max_page_size = ws.get("max_page_size", 200)

    eff_limit = limit if limit is not None else default_page_size
    if not isinstance(eff_limit, int) or eff_limit < 1:
        _log_request("rejected", 400, "VALIDATION_ERROR", "limit must be >= 1")
        return _err("VALIDATION_ERROR", "limit must be >= 1")
    if eff_limit > max_page_size:
        _log_request("rejected", 400, "VALIDATION_ERROR", f"limit must be <= {max_page_size}")
        return _err("VALIDATION_ERROR", f"limit must be <= {max_page_size}")
    eff_start = start_at if start_at is not None else 0

    conns = _load("atlassian_connections.json")
    conn = next((c for c in conns if c.get("connection_id") == connection_id and c.get("workspace_id") == workspace_id), None)
    if not conn:
        _log_request("failed", 401, "UNAUTHORIZED", "connection not accessible to workspace")
        return _err("UNAUTHORIZED", "connection not accessible to workspace")
    if conn.get("product") != "jira":
        _log_request("rejected", 400, "VALIDATION_ERROR", "connection_id must refer to a Jira connection")
        return _err("VALIDATION_ERROR", "connection_id must refer to a Jira connection")
    if conn.get("status") != "active":
        _log_request("failed", 503, "UPSTREAM_UNAVAILABLE", "jira connection is not active")
        return _err("CONFLICT", "jira connection is not active", error_code="UPSTREAM_UNAVAILABLE")

    # Behavior: read cache (no real upstream). If refresh requested, mark last_sync_at and touch fetched_at on matching issues.
    jira_entities = _load("jira_entities.json")

    # Identify project row (optional)
    proj_row = next((e for e in jira_entities
                     if e.get("workspace_id") == workspace_id and e.get("connection_id") == connection_id
                     and e.get("entity_type") == "project" and e.get("external_key") == project_key
                     and e.get("status") == "active"), None)

    # Filter issues belonging to project. We infer project by key prefix "PROJ-" when possible, else by json_payload.fields.project.key
    def _issue_matches(e):
        if e.get("entity_type") != "issue" or e.get("status") != "active":
            return False
        if e.get("workspace_id") != workspace_id or e.get("connection_id") != connection_id:
            return False
        ek = e.get("external_key") or ""
        if isinstance(ek, str) and ek.startswith(project_key + "-"):
            return True
        jp = e.get("json_payload") if isinstance(e.get("json_payload"), dict) else {}
        fields_obj = jp.get("fields") if isinstance(jp.get("fields"), dict) else {}
        proj = fields_obj.get("project") if isinstance(fields_obj.get("project"), dict) else {}
        if proj.get("key") == project_key:
            return True
        return False

    issues = [e for e in jira_entities if _issue_matches(e)]

    # Sort by external_key for stable pagination
    issues.sort(key=lambda r: (r.get("external_key") or "", r.get("external_id") or ""))

    total = len(issues)
    page = issues[eff_start: eff_start + eff_limit]
    has_more = (eff_start + eff_limit) < total
    next_cursor = (eff_start + eff_limit) if has_more else None

    # Apply field/expand shaping (best-effort on cached json_payload)
    field_list = None
    if fields:
        field_list = [f.strip() for f in fields.split(",") if f.strip()]
    expand_list = None
    if expand:
        expand_list = [x.strip() for x in expand.split(",") if x.strip()]

    shaped_issues = []
    affected = []
    for e in page:
        jp = e.get("json_payload") if isinstance(e.get("json_payload"), dict) else {}
        issue_obj = dict(jp)  # copy
        if field_list is not None:
            fobj = issue_obj.get("fields") if isinstance(issue_obj.get("fields"), dict) else {}
            issue_obj["fields"] = {k: v for k, v in fobj.items() if k in field_list}
        if expand_list is not None:
            issue_obj["expand"] = ",".join(expand_list)
        shaped_issues.append(issue_obj)
        affected.append({"system": "jira", "entity_type": "issue", "external_id": e.get("external_id")})

    if refresh:
        # Touch fetched_at and workspace last_sync_at for the issues returned (simulation of refresh).
        changed = False
        for e in page:
            if isinstance(e, dict):
                if e.get("fetched_at") != now:
                    e["fetched_at"] = now
                    e["updated_at"] = now
                    changed = True
        if changed:
            _save("jira_entities.json", jira_entities)
        # Update connection last_sync_at
        conn_changed = False
        for c in conns:
            if c.get("connection_id") == connection_id:
                if c.get("last_sync_at") != now:
                    c["last_sync_at"] = now
                    c["updated_at"] = now
                    conn_changed = True
                break
        if conn_changed:
            _save("atlassian_connections.json", conns)

    result = {
        "project": (proj_row.get("json_payload") if proj_row and isinstance(proj_row.get("json_payload"), dict) else {"key": project_key}),
        "startAt": eff_start,
        "maxResults": eff_limit,
        "total": total,
        "isLast": not has_more,
        "nextCursor": next_cursor,
        "issues": shaped_issues,
        "latency_ms": int((time.time() - t0) * 1000)
    }

    _log_request("succeeded", 200, None, None, result_json=result, affected_entities=affected)
    return result

