    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        import random, string
        return f"{prefix}_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{''.join(random.choice(string.ascii_lowercase+string.digits) for _ in range(10))}"

    def _log_request(status, http_status=None, error_code=None, error_message=None, result_json=None, affected_entities=None):
        tool_requests = _load("tool_requests.json")
        tr_id = _new_id("ais_trq")
        row = {
            "tool_request_id": tr_id,
            "workspace_id": workspace_id,
            "connection_id": connection_id,
            "tool_name": "jira_download_attachments",
            "params_json": {
                "issue_key": issue_key,
                "target_dir": target_dir,
                "attachment_ids": attachment_ids,
                "refresh": bool(refresh) if refresh is not None else False
            },
            "status": status,
            "http_status": http_status,
            "error_code": error_code,
            "error_message": error_message,
            "result_json": result_json,
            "affected_entities": affected_entities,
            "started_at": now,
            "finished_at": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
            "created_at": now,
            "updated_at": now
        }
        tool_requests.append(row)
        _save("tool_requests.json", tool_requests)
        return row

    # Validate inputs
    if not isinstance(workspace_id, str) or not workspace_id:
        _log_request("rejected", 400, "VALIDATION_ERROR", "workspace_id must be a non-empty string")
        return _err("VALIDATION_ERROR", "workspace_id must be a non-empty string")
    if not isinstance(connection_id, str) or not connection_id:
        _log_request("rejected", 400, "VALIDATION_ERROR", "connection_id must be a non-empty string")
        return _err("VALIDATION_ERROR", "connection_id must be a non-empty string")
    if not isinstance(issue_key, str) or not issue_key or not re.match(r"^[A-Z][A-Z0-9_]+-\d+$", issue_key):
        _log_request("rejected", 400, "VALIDATION_ERROR", "issue_key must look like a Jira issue key (e.g., PROJ-123)")
        return _err("VALIDATION_ERROR", "issue_key must look like a Jira issue key (e.g., PROJ-123)")
    if not isinstance(target_dir, str) or not target_dir:
        _log_request("rejected", 400, "VALIDATION_ERROR", "target_dir must be a non-empty string")
        return _err("VALIDATION_ERROR", "target_dir must be a non-empty string")
    if attachment_ids is not None:
        if not isinstance(attachment_ids, list) or any((not isinstance(x, str) or not x) for x in attachment_ids):
            _log_request("rejected", 400, "VALIDATION_ERROR", "attachment_ids must be an array of non-empty strings when provided")
            return _err("VALIDATION_ERROR", "attachment_ids must be an array of non-empty strings when provided")
    if refresh is not None and not isinstance(refresh, bool):
        _log_request("rejected", 400, "VALIDATION_ERROR", "refresh must be a boolean when provided")
        return _err("VALIDATION_ERROR", "refresh must be a boolean when provided")

    workspaces = _load("workspaces.json")
    ws = next((w for w in workspaces if w.get("workspace_id") == workspace_id), None)
    if not ws:
        _log_request("failed", 404, "NOT_FOUND", "workspace not found")
        return _err("NOT_FOUND", "workspace not found")
    if ws.get("status") != "active":
        _log_request("rejected", 403, "WORKSPACE_INACTIVE", "workspace is not active")
        return _err("UNAUTHORIZED", "workspace is not active", error_code="WORKSPACE_INACTIVE")

    # read-only mode enforcement (mutating tool)
    if bool(ws.get("read_only_mode")):
        _log_request("rejected", 403, "READ_ONLY_MODE", "workspace is in read-only mode")
        return _err("CONFLICT", "workspace is in read-only mode", error_code="READ_ONLY_MODE")

    conns = _load("atlassian_connections.json")
    conn = next((c for c in conns if c.get("connection_id") == connection_id and c.get("workspace_id") == workspace_id), None)
    if not conn:
        _log_request("failed", 401, "UNAUTHORIZED", "connection not accessible to workspace")
        return _err("UNAUTHORIZED", "connection not accessible to workspace")
    if conn.get("product") != "jira":
        _log_request("rejected", 400, "VALIDATION_ERROR", "connection_id must refer to a Jira connection")
        return _err("VALIDATION_ERROR", "connection_id must refer to a Jira connection")
    if conn.get("status") != "active":
        _log_request("failed", 503, "UPSTREAM_UNAVAILABLE", "jira connection is not active")
        return _err("CONFLICT", "jira connection is not active", error_code="UPSTREAM_UNAVAILABLE")

    # Ensure target_dir exists / create
    try:
        os.makedirs(target_dir, exist_ok=True)
    except OSError as e:
        _log_request("rejected", 400, "VALIDATION_ERROR", f"target_dir is not writable/creatable: {e}")
        return _err("VALIDATION_ERROR", f"target_dir is not writable/creatable: {e}")

    jira_entities = _load("jira_entities.json")
    issue_row = next((e for e in jira_entities
                      if e.get("workspace_id") == workspace_id and e.get("connection_id") == connection_id
                      and e.get("entity_type") == "issue" and e.get("external_key") == issue_key
                      and e.get("status") == "active"), None)
    if not issue_row:
        _log_request("failed", 404, "NOT_FOUND", "issue not found in cache")
        return _err("NOT_FOUND", "issue not found")

    issue_external_id = issue_row.get("external_id")

    # Refresh simulation: touch issue fetched_at
    if refresh:
        issue_row["fetched_at"] = now
        issue_row["updated_at"] = now
        _save("jira_entities.json", jira_entities)

    # Find attachments for issue
    attachments = [e for e in jira_entities
                   if e.get("workspace_id") == workspace_id and e.get("connection_id") == connection_id
                   and e.get("entity_type") == "attachment" and e.get("status") == "active"
                   and e.get("parent_external_id") == issue_external_id]

    if attachment_ids is not None:
        wanted = set(attachment_ids)
        attachments = [a for a in attachments if a.get("external_id") in wanted]
        missing = [aid for aid in attachment_ids if aid not in set(a.get("external_id") for a in attachments)]
        if missing:
            _log_request("rejected", 400, "VALIDATION_ERROR", "one or more attachment_ids are not present on the issue", missing_attachment_ids=missing)
            return _err("VALIDATION_ERROR", "one or more attachment_ids are not present on the issue", missing_attachment_ids=missing)

    # If no attachments to download, that's a successful no-op? For this tool, require effect: if request specifies ids,
    # we validated presence; if omitted and none exist, return empty summary (read-like). Still we will log attempts.
    results = []
    affected = [{"system": "jira", "entity_type": "issue", "external_id": issue_external_id}]
    for a in attachments:
        jp = a.get("json_payload") if isinstance(a.get("json_payload"), dict) else {}
        filename = jp.get("filename") if isinstance(jp.get("filename"), str) and jp.get("filename") else f"attachment_{a.get('external_id')}"
        safe_name = re.sub(r"[^A-Za-z0-9._-]+", "_", filename).strip("._") or f"attachment_{a.get('external_id')}"
        path = os.path.join(target_dir, safe_name)

        # Simulate download content using stored metadata (offline)
        content = {
            "attachment_id": a.get("external_id"),
            "issue_key": issue_key,
            "downloaded_at": now,
            "metadata": jp
        }
        try:
            with open(path, "w", encoding="utf-8") as f:
                json.dump(content, f, ensure_ascii=False, indent=2)
        except OSError as e:
            # Partial failures are recorded as failed request (real systems may be partial; here we fail fast)
            _log_request("failed", 500, "UPSTREAM_UNAVAILABLE", f"failed to write attachment to disk: {e}")
            return _err("CONFLICT", f"failed to write attachment to disk: {e}", error_code="UPSTREAM_UNAVAILABLE")

        results.append({
            "attachment_id": a.get("external_id"),
            "filename": filename,
            "saved_path": path,
            "bytes_written": os.path.getsize(path) if os.path.exists(path) else None
        })
        affected.append({"system": "jira", "entity_type": "attachment", "external_id": a.get("external_id")})

    result = {
        "issue_key": issue_key,
        "target_dir": target_dir,
        "requested_attachment_ids": attachment_ids,
        "downloaded": results,
        "downloaded_count": len(results),
        "latency_ms": int((time.time() - t0) * 1000)
    }
    _log_request("succeeded", 200, None, None, result_json=result, affected_entities=affected)
    return result

def jira_get_agile_boards(workspace_id, connection_id, board_name=None, project_key=None, board_type=None, start_at=None, limit=None, refresh=None, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0275000" if __import__("os").path.isdir("./environment_mix/0275000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        n = int(time.time() * 1000)
        s = ""
        while n > 0:
            n, r = divmod(n, 36)
            s = alphabet[r] + s
        s = s.rjust(10, "0")
        return f"{prefix}{s}"

    def _log_request(tool_name, wsp_id, con_id, params, status, http_status=None, error_code=None, error_message=None, result_json=None, affected_entities=None, started_at=None, finished_at=None):
        reqs = _load("tool_requests.json")
        tr_id = _new_id("ais_trq_")
        row = {
            "tool_request_id": tr_id,
            "workspace_id": wsp_id,
            "connection_id": con_id,
            "tool_name": tool_name,
            "params_json": params if isinstance(params, dict) else {},
            "status": status,
            "http_status": http_status,
            "error_code": error_code,
            "error_message": error_message,
            "result_json": result_json,
            "affected_entities": affected_entities,
            "started_at": started_at,
            "finished_at": finished_at,
            "created_at": now,
            "updated_at": now,
        }
        reqs.append(row)
        _save("tool_requests.json", reqs)
        return tr_id

    def _reject(wsp_id, con_id, params, api_error_code, api_error_message, http_status=403):
        started = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        finished = started
        _log_request(
            "jira_get_agile_boards",
            wsp_id,
            con_id,
            params,
            status="rejected",
            http_status=http_status,
            error_code=api_error_code,
            error_message=api_error_message,
            result_json=None,
            affected_entities=[],
            started_at=started,
            finished_at=finished,
        )
        return _err("UNAUTHORIZED" if api_error_code in ("WORKSPACE_INACTIVE", "UPSTREAM_UNAVAILABLE") else "VALIDATION_ERROR", api_error_message, error_code=api_error_code)

    # Validate required
    if not isinstance(workspace_id, str) or not re.match(r"^ais_wsp_[0-9A-Z]{10,}$", workspace_id):
        _log_request("jira_get_agile_boards", workspace_id if isinstance(workspace_id, str) else "unknown", connection_id if isinstance(connection_id, str) else None,
                     {"workspace_id": workspace_id, "connection_id": connection_id}, status="failed", http_status=400,
                     error_code="VALIDATION_ERROR", error_message="Invalid workspace_id.", started_at=now, finished_at=now)
        return _err("VALIDATION_ERROR", "Invalid workspace_id.")
    if not isinstance(connection_id, str) or not re.match(r"^ais_con_[0-9A-Z]{10,}$", connection_id):
        _log_request("jira_get_agile_boards", workspace_id, connection_id if isinstance(connection_id, str) else None,
                     {"workspace_id": workspace_id, "connection_id": connection_id}, status="failed", http_status=400,
                     error_code="VALIDATION_ERROR", error_message="Invalid connection_id.", started_at=now, finished_at=now)
        return _err("VALIDATION_ERROR", "Invalid connection_id.")

    if board_name is not None and not isinstance(board_name, str):
        return _err("VALIDATION_ERROR", "board_name must be a string.")
    if project_key is not None and not isinstance(project_key, str):
        return _err("VALIDATION_ERROR", "project_key must be a string.")
    if board_type is not None:
        if not isinstance(board_type, str) or board_type not in ("scrum", "kanban"):
            return _err("VALIDATION_ERROR", "board_type must be one of: scrum, kanban.")
    if start_at is not None and (not isinstance(start_at, int) or start_at < 0):
        return _err("VALIDATION_ERROR", "start_at must be an integer >= 0.")
    if limit is not None and (not isinstance(limit, int) or limit < 1):
        return _err("VALIDATION_ERROR", "limit must be an integer >= 1.")
    if refresh is not None and not isinstance(refresh, bool):
        return _err("VALIDATION_ERROR", "refresh must be a boolean.")

    # Resolve workspace
    workspaces = _load("workspaces.json")
    wsp = next((w for w in workspaces if w.get("workspace_id") == workspace_id), None)
    if not wsp:
        _log_request("jira_get_agile_boards", workspace_id, connection_id, {"workspace_id": workspace_id, "connection_id": connection_id}, status="failed",
                     http_status=404, error_code="NOT_FOUND", error_message="Workspace not found.", started_at=now, finished_at=now)
        return _err("NOT_FOUND", "Workspace not found.")
    if wsp.get("status") != "active":
        params = {"board_name": board_name, "project_key": project_key, "board_type": board_type, "start_at": start_at, "limit": limit, "refresh": refresh}
        return _reject(workspace_id, connection_id, params, "WORKSPACE_INACTIVE", "Workspace is not active.", http_status=403)

    # Pagination defaults/enforcement
    dps = wsp.get("default_page_size", 25)
    mps = wsp.get("max_page_size", 200)
    if not isinstance(dps, int) or dps < 1:
        dps = 25
    if not isinstance(mps, int) or mps < 1:
        mps = 200
    if start_at is None:
        start_at = 0
    if limit is None:
        limit = dps
    if limit < 1 or limit > mps:
        params = {"board_name": board_name, "project_key": project_key, "board_type": board_type, "start_at": start_at, "limit": limit, "refresh": refresh}
        _log_request("jira_get_agile_boards", workspace_id, connection_id, params, status="failed", http_status=400,
                     error_code="VALIDATION_ERROR", error_message="limit out of range for workspace.", started_at=now, finished_at=now)
        return _err("VALIDATION_ERROR", f"limit must be between 1 and {mps}.")

    # Resolve Jira connection must be active and match id+workspace+product
    cons = _load("atlassian_connections.json")
    con = next((c for c in cons if c.get("connection_id") == connection_id and c.get("workspace_id") == workspace_id and c.get("product") == "jira"), None)
    if not con or con.get("status") != "active":
        params = {"board_name": board_name, "project_key": project_key, "board_type": board_type, "start_at": start_at, "limit": limit, "refresh": refresh}
        return _reject(workspace_id, connection_id, params, "UPSTREAM_UNAVAILABLE", "No active Jira connection available for this workspace/connection.", http_status=503)

    started = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Refresh semantics: offline store, so we record the intent and touch last_sync_at.
    if refresh is True:
        con["last_sync_at"] = started
        con["updated_at"] = started
        # persist connection update
        for i, c in enumerate(cons):
            if c.get("connection_id") == connection_id:
                cons[i] = con
                break
        _save("atlassian_connections.json", cons)

    entities = _load("jira_entities.json")

    def _text(v):
        if v is None:
            return ""
        if isinstance(v, str):
            return v
        return str(v)

    # Boards cached as jira_entities(entity_type='board'), optionally store "type" in json_payload.type
    rows = [e for e in entities if e.get("workspace_id") == workspace_id and e.get("connection_id") == connection_id and e.get("entity_type") == "board" and e.get("status") == "active"]

    if board_name:
        bn = board_name.strip().lower()
        if bn:
            def _match_name(e):
                title = _text(e.get("title")).lower()
                jp = e.get("json_payload") if isinstance(e.get("json_payload"), dict) else {}
                n2 = _text(jp.get("name")).lower()
                return (bn in title) or (bn in n2)
            rows = [e for e in rows if _match_name(e)]

    if project_key:
        pk = project_key.strip().upper()
        if pk:
            def _match_project(e):
                jp = e.get("json_payload") if isinstance(e.get("json_payload"), dict) else {}
                # common fields: location.projectKey or filterQueryProjectKey (best-effort)
                loc = jp.get("location")
                if isinstance(loc, dict):
                    if _text(loc.get("projectKey")).upper() == pk:
                        return True
                    proj = loc.get("project")
                    if isinstance(proj, dict) and _text(proj.get("key")).upper() == pk:
                        return True
                if _text(jp.get("projectKey")).upper() == pk:
                    return True
                if _text(jp.get("filterProjectKey")).upper() == pk:
                    return True
                return False
            rows = [e for e in rows if _match_project(e)]

    if board_type:
        bt = board_type.lower()
        def _match_type(e):
            jp = e.get("json_payload") if isinstance(e.get("json_payload"), dict) else {}
            t = _text(jp.get("type")).lower()
            if not t:
                t = _text(jp.get("boardType")).lower()
            return t == bt
        rows = [e for e in rows if _match_type(e)]

    # Sort: stable by title then external_id
    rows.sort(key=lambda e: (_text(e.get("title")).lower(), _text(e.get("external_id"))))

    total = len(rows)
    page = rows[start_at:start_at + limit]
    has_more = (start_at + limit) < total
    next_cursor = (start_at + limit) if has_more else None

    boards = []
    affected = []
    for e in page:
        jp = e.get("json_payload") if isinstance(e.get("json_payload"), dict) else {}
        obj = dict(jp) if jp else {}
        if "id" not in obj and e.get("external_id") is not None:
            obj["id"] = e.get("external_id")
        if "name" not in obj and e.get("title") is not None:
            obj["name"] = e.get("title")
        boards.append(obj)
        affected.append({"system": "jira", "entity_type": "board", "external_id": e.get("external_id")})

    result = {"values": boards, "startAt": start_at, "maxResults": limit, "total": total, "isLast": not has_more}
    finished = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    _log_request(
        "jira_get_agile_boards",
        workspace_id,
        connection_id,
        {
            "board_name": board_name,
            "project_key": project_key,
            "board_type": board_type,
            "start_at": start_at,
            "limit": limit,
            "refresh": refresh,
        },
        status="succeeded",
        http_status=200,
        error_code=None,
        error_message=None,
        result_json=result,
        affected_entities=affected,
        started_at=started,
        finished_at=finished,
    )

    return {"boards": boards, "start_at": start_at, "limit": limit, "total": total, "has_more": has_more, "next_cursor": next_cursor, "latency_ms": int((time.time() - t0) * 1000)}

def jira_get_board_issues(workspace_id, connection_id, board_id, jql=None, fields=None, expand=None, start_at=None, limit=None, refresh=None, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0275000" if __import__("os").path.isdir("./environment_mix/0275000") else "/app/database")
    def _load(n):
