            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        n = int(time.time() * 1000)
        s = ""
        while n > 0:
            n, r = divmod(n, 36)
            s = alphabet[r] + s
        s = s.rjust(10, "0")
        return f"{prefix}{s}"

    def _log_request(tool_name, wsp_id, con_id, params, status, http_status=None, error_code=None, error_message=None, result_json=None, affected_entities=None, started_at=None, finished_at=None):
