        tr_id = _new_id("ais_trq_")
        row = {
            "tool_request_id": tr_id,
            "workspace_id": wsp_id,
            "connection_id": con_id,
            "tool_name": tool_name,
            "params_json": params if isinstance(params, dict) else {},
            "status": status,
            "http_status": http_status,
            "error_code": error_code,
            "error_message": error_message,
            "result_json": result_json,
            "affected_entities": affected_entities,
            "started_at": started_at,
            "finished_at": finished_at,
            "created_at": now,
            "updated_at": now,
        }
        reqs.append(row)
        _save("tool_requests.json", reqs)
        return tr_id

    def _reject(api_error_code, api_error_message, params, http_status=403):
        started = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        finished = started
        _log_request(
            "jira_get_board_issues",
            workspace_id,
            connection_id,
            params,
            status="rejected",
            http_status=http_status,
            error_code=api_error_code,
            error_message=api_error_message,
            result_json=None,
            affected_entities=[],
            started_at=started,
            finished_at=finished,
        )
        return _err("UNAUTHORIZED" if api_error_code in ("WORKSPACE_INACTIVE", "UPSTREAM_UNAVAILABLE") else "VALIDATION_ERROR", api_error_message, error_code=api_error_code)

    # Validate
    if not isinstance(workspace_id, str) or not re.match(r"^ais_wsp_[0-9A-Z]{10,}$", workspace_id):
        _log_request("jira_get_board_issues", workspace_id if isinstance(workspace_id, str) else "unknown", connection_id if isinstance(connection_id, str) else None,
                     {"workspace_id": workspace_id, "connection_id": connection_id, "board_id": board_id}, status="failed", http_status=400,
                     error_code="VALIDATION_ERROR", error_message="Invalid workspace_id.", started_at=now, finished_at=now)
        return _err("VALIDATION_ERROR", "Invalid workspace_id.")
    if not isinstance(connection_id, str) or not re.match(r"^ais_con_[0-9A-Z]{10,}$", connection_id):
        _log_request("jira_get_board_issues", workspace_id, connection_id if isinstance(connection_id, str) else None,
                     {"workspace_id": workspace_id, "connection_id": connection_id, "board_id": board_id}, status="failed", http_status=400,
                     error_code="VALIDATION_ERROR", error_message="Invalid connection_id.", started_at=now, finished_at=now)
        return _err("VALIDATION_ERROR", "Invalid connection_id.")
    if not isinstance(board_id, str) or not board_id.strip():
        return _err("VALIDATION_ERROR", "board_id must be a non-empty string.")
    if jql is not None and not isinstance(jql, str):
        return _err("VALIDATION_ERROR", "jql must be a string.")
    if fields is not None and not isinstance(fields, str):
        return _err("VALIDATION_ERROR", "fields must be a string.")
    if expand is not None and not isinstance(expand, str):
        return _err("VALIDATION_ERROR", "expand must be a string.")
    if start_at is not None and (not isinstance(start_at, int) or start_at < 0):
        return _err("VALIDATION_ERROR", "start_at must be an integer >= 0.")
    if limit is not None and (not isinstance(limit, int) or limit < 1):
        return _err("VALIDATION_ERROR", "limit must be an integer >= 1.")
    if refresh is not None and not isinstance(refresh, bool):
        return _err("VALIDATION_ERROR", "refresh must be a boolean.")

    workspaces = _load("workspaces.json")
    wsp = next((w for w in workspaces if w.get("workspace_id") == workspace_id), None)
    if not wsp:
        _log_request("jira_get_board_issues", workspace_id, connection_id, {"board_id": board_id}, status="failed", http_status=404,
                     error_code="NOT_FOUND", error_message="Workspace not found.", started_at=now, finished_at=now)
        return _err("NOT_FOUND", "Workspace not found.")
    if wsp.get("status") != "active":
        params = {"board_id": board_id, "jql": jql, "fields": fields, "expand": expand, "start_at": start_at, "limit": limit, "refresh": refresh}
        return _reject("WORKSPACE_INACTIVE", "Workspace is not active.", params, http_status=403)

    dps = wsp.get("default_page_size", 25)
    mps = wsp.get("max_page_size", 200)
    if not isinstance(dps, int) or dps < 1:
        dps = 25
    if not isinstance(mps, int) or mps < 1:
        mps = 200
    if start_at is None:
        start_at = 0
    if limit is None:
        limit = dps
    if limit < 1 or limit > mps:
        params = {"board_id": board_id, "jql": jql, "fields": fields, "expand": expand, "start_at": start_at, "limit": limit, "refresh": refresh}
        _log_request("jira_get_board_issues", workspace_id, connection_id, params, status="failed", http_status=400,
                     error_code="VALIDATION_ERROR", error_message="limit out of range for workspace.", started_at=now, finished_at=now)
        return _err("VALIDATION_ERROR", f"limit must be between 1 and {mps}.")

    cons = _load("atlassian_connections.json")
    con = next((c for c in cons if c.get("connection_id") == connection_id and c.get("workspace_id") == workspace_id and c.get("product") == "jira"), None)
    if not con or con.get("status") != "active":
        params = {"board_id": board_id, "jql": jql, "fields": fields, "expand": expand, "start_at": start_at, "limit": limit, "refresh": refresh}
        return _reject("UPSTREAM_UNAVAILABLE", "No active Jira connection available for this workspace/connection.", params, http_status=503)

    started = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    if refresh is True:
        con["last_sync_at"] = started
        con["updated_at"] = started
        for i, c in enumerate(cons):
            if c.get("connection_id") == connection_id:
                cons[i] = con
                break
        _save("atlassian_connections.json", cons)

    entities = _load("jira_entities.json")

    # Verify board exists in cache (best effort); if missing, read returns empty set (no error).
    board_entity = next((e for e in entities if e.get("workspace_id") == workspace_id and e.get("connection_id") == connection_id and e.get("entity_type") == "board" and e.get("external_id") == board_id and e.get("status") == "active"), None)

    issues = [e for e in entities if e.get("workspace_id") == workspace_id and e.get("connection_id") == connection_id and e.get("entity_type") == "issue" and e.get("status") == "active"]

    # Board association heuristic: issue.json_payload.boardId == board_id OR issue.json_payload.fields.customfield... contains board_id
    def _issue_matches_board(e):
        jp = e.get("json_payload") if isinstance(e.get("json_payload"), dict) else {}
        if str(jp.get("boardId")) == str(board_id):
            return True
        fields_obj = jp.get("fields")
        if isinstance(fields_obj, dict):
            for _, v in fields_obj.items():
                if isinstance(v, (str, int)) and str(v) == str(board_id):
                    return True
                if isinstance(v, dict) and ("boardId" in v or "id" in v):
                    if str(v.get("boardId")) == str(board_id) or str(v.get("id")) == str(board_id):
                        return True
                if isinstance(v, list):
                    for it in v:
                        if isinstance(it, (str, int)) and str(it) == str(board_id):
                            return True
                        if isinstance(it, dict):
                            if str(it.get("boardId")) == str(board_id) or str(it.get("id")) == str(board_id):
                                return True
        return False

    if board_entity is not None:
        issues = [e for e in issues if _issue_matches_board(e)]
    else:
        # If we don't know the board, we can't reliably map; return empty but still succeed.
        issues = []

    # Apply a minimal local "JQL" subset (best-effort) via keyword search in indexed_text/title/external_key
    if isinstance(jql, str) and jql.strip():
        q = jql.strip().lower()
        def _match_jql_like(e):
            if q in (e.get("external_key") or "").lower():
                return True
            if q in (e.get("title") or "").lower():
                return True
            if q in (e.get("indexed_text") or "").lower():
                return True
            # allow 'text ~ "foo"' pattern
            m = re.search(r'~\s*"([^"]+)"', q)
            if m:
                needle = m.group(1).lower()
                return needle in (e.get("indexed_text") or "").lower() or needle in (e.get("title") or "").lower()
            return False
        issues = [e for e in issues if _match_jql_like(e)]

    # Stable ordering by external_key then external_id
    def _k(e):
        ek = e.get("external_key")
        return ((ek or "").upper(), str(e.get("external_id") or ""))
    issues.sort(key=_k)

    total = len(issues)
    page = issues[start_at:start_at + limit]
    has_more = (start_at + limit) < total

    # Fields/expand are passed through as selection hints (offline)
    wanted_fields = None
    if isinstance(fields, str) and fields.strip():
        wanted_fields = [f.strip() for f in fields.split(",") if f.strip()]

    def _project_issue_obj(e):
        jp = e.get("json_payload") if isinstance(e.get("json_payload"), dict) else {}
        obj = dict(jp) if jp else {}
        if "id" not in obj and e.get("external_id") is not None:
            obj["id"] = e.get("external_id")
        if "key" not in obj and e.get("external_key") is not None:
            obj["key"] = e.get("external_key")
        if "fields" in obj and isinstance(obj["fields"], dict) and wanted_fields is not None:
            filtered = {}
            for f in wanted_fields:
                if f in obj["fields"]:
                    filtered[f] = obj["fields"][f]
            # Always include summary if present
            if "summary" in obj["fields"]:
                filtered.setdefault("summary", obj["fields"]["summary"])
            obj["fields"] = filtered
        return obj

    issues_out = [_project_issue_obj(e) for e in page]
    affected = [{"system": "jira", "entity_type": "issue", "external_id": e.get("external_id")} for e in page]
    if board_entity is not None:
        affected.insert(0, {"system": "jira", "entity_type": "board", "external_id": board_id})

    result = {
        "startAt": start_at,
        "maxResults": limit,
        "total": total,
        "issues": issues_out,
        "expand": expand,
        "jql": jql,
        "boardId": board_id,
    }

    finished = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    _log_request(
        "jira_get_board_issues",
        workspace_id,
        connection_id,
        {
            "board_id": board_id,
            "jql": jql,
            "fields": fields,
            "expand": expand,
            "start_at": start_at,
            "limit": limit,
            "refresh": refresh,
        },
        status="succeeded",
        http_status=200,
        error_code=None,
        error_message=None,
        result_json=result,
        affected_entities=affected,
        started_at=started,
        finished_at=finished,
    )

    return {"search_results": result, "has_more": has_more, "next_cursor": (start_at + limit) if has_more else None, "latency_ms": int((time.time() - t0) * 1000)}

