        _log_request("jira_get_sprints_from_board", workspace_id, connection_id, {"board_id": board_id}, status="failed", http_status=404,
                     error_code="NOT_FOUND", error_message="Workspace not found.", started_at=now, finished_at=now)
        return _err("NOT_FOUND", "Workspace not found.")
    if wsp.get("status") != "active":
        params = {"board_id": board_id, "state": state, "start_at": start_at, "limit": limit, "refresh": refresh}
        return _reject("WORKSPACE_INACTIVE", "Workspace is not active.", params, http_status=403)

    dps = wsp.get("default_page_size", 25)
    mps = wsp.get("max_page_size", 200)
    if not isinstance(dps, int) or dps < 1:
        dps = 25
    if not isinstance(mps, int) or mps < 1:
        mps = 200
    if start_at is None:
        start_at = 0
    if limit is None:
        limit = dps
    if limit < 1 or limit > mps:
        params = {"board_id": board_id, "state": state, "start_at": start_at, "limit": limit, "refresh": refresh}
        _log_request("jira_get_sprints_from_board", workspace_id, connection_id, params, status="failed", http_status=400,
                     error_code="VALIDATION_ERROR", error_message="limit out of range for workspace.", started_at=now, finished_at=now)
        return _err("VALIDATION_ERROR", f"limit must be between 1 and {mps}.")

    cons = _load("atlassian_connections.json")
    con = next((c for c in cons if c.get("connection_id") == connection_id and c.get("workspace_id") == workspace_id and c.get("product") == "jira"), None)
    if not con or con.get("status") != "active":
        params = {"board_id": board_id, "state": state, "start_at": start_at, "limit": limit, "refresh": refresh}
        return _reject("UPSTREAM_UNAVAILABLE", "No active Jira connection available for this workspace/connection.", params, http_status=503)

    started = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    if refresh is True:
        con["last_sync_at"] = started
        con["updated_at"] = started
        for i, c in enumerate(cons):
            if c.get("connection_id") == connection_id:
                cons[i] = con
                break
        _save("atlassian_connections.json", cons)

    entities = _load("jira_entities.json")
    # Sprints cached as jira_entities(entity_type='sprint'), parent_external_id = board_id
    sprints = [e for e in entities if e.get("workspace_id") == workspace_id and e.get("connection_id") == connection_id and e.get("entity_type") == "sprint" and e.get("status") == "active" and str(e.get("parent_external_id")) == str(board_id)]

    if state:
        st = state.lower()
        def _match_state(e):
            jp = e.get("json_payload") if isinstance(e.get("json_payload"), dict) else {}
            s = (jp.get("state") or jp.get("status") or "").lower()
            return s == st
        sprints = [e for e in sprints if _match_state(e)]

    # Sort by startDate/endDate if present else title/id
    def _sort_key(e):
        jp = e.get("json_payload") if isinstance(e.get("json_payload"), dict) else {}
        sd = jp.get("startDate") or ""
        ed = jp.get("endDate") or ""
        name = (e.get("title") or "").lower()
        return (sd, ed, name, str(e.get("external_id") or ""))
    sprints.sort(key=_sort_key)

    total = len(sprints)
    page = sprints[start_at:start_at + limit]
    has_more = (start_at + limit) < total
    next_cursor = (start_at + limit) if has_more else None

    out = []
    affected = [{"system": "jira", "entity_type": "board", "external_id": board_id}]
    for e in page:
        jp = e.get("json_payload") if isinstance(e.get("json_payload"), dict) else {}
        obj = dict(jp) if jp else {}
        if "id" not in obj and e.get("external_id") is not None:
            obj["id"] = e.get("external_id")
        if "name" not in obj and e.get("title") is not None:
            obj["name"] = e.get("title")
        out.append(obj)
        affected.append({"system": "jira", "entity_type": "sprint", "external_id": e.get("external_id")})

    result = {"values": out, "startAt": start_at, "maxResults": limit, "total": total, "isLast": not has_more, "boardId": board_id, "state": state}
    finished = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    _log_request(
        "jira_get_sprints_from_board",
        workspace_id,
        connection_id,
        {"board_id": board_id, "state": state, "start_at": start_at, "limit": limit, "refresh": refresh},
        status="succeeded",
        http_status=200,
        error_code=None,
        error_message=None,
        result_json=result,
        affected_entities=affected,
        started_at=started,
        finished_at=finished,
    )

    return {"sprints": out, "start_at": start_at, "limit": limit, "total": total, "has_more": has_more, "next_cursor": next_cursor, "latency_ms": int((time.time() - t0) * 1000)}

def jira_get_sprint_issues(workspace_id, connection_id, sprint_id, fields=None, start_at=None, limit=None, refresh=None, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0275000" if __import__("os").path.isdir("./environment_mix/0275000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        n = int(time.time() * 1000)
        s = ""
        while n > 0:
            n, r = divmod(n, 36)
            s = alphabet[r] + s
        s = s.rjust(10, "0")
        return f"{prefix}{s}"

    def _log_request(tool_name, wsp_id, con_id, params, status, http_status=None, error_code=None, error_message=None, result_json=None, affected_entities=None, started_at=None, finished_at=None):
        reqs = _load("tool_requests.json")
        tr_id = _new_id("ais_trq_")
        row = {
            "tool_request_id": tr_id,
            "workspace_id": wsp_id,
            "connection_id": con_id,
            "tool_name": tool_name,
            "params_json": params if isinstance(params, dict) else {},
            "status": status,
            "http_status": http_status,
            "error_code": error_code,
            "error_message": error_message,
            "result_json": result_json,
            "affected_entities": affected_entities,
            "started_at": started_at,
            "finished_at": finished_at,
            "created_at": now,
            "updated_at": now,
        }
        reqs.append(row)
        _save("tool_requests.json", reqs)
        return tr_id

    def _reject(api_error_code, api_error_message, params, http_status=403):
        started = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        finished = started
        _log_request(
            "jira_get_sprint_issues",
            workspace_id,
            connection_id,
            params,
            status="rejected",
            http_status=http_status,
            error_code=api_error_code,
            error_message=api_error_message,
            result_json=None,
            affected_entities=[],
            started_at=started,
            finished_at=finished,
        )
        return _err("UNAUTHORIZED" if api_error_code in ("WORKSPACE_INACTIVE", "UPSTREAM_UNAVAILABLE") else "VALIDATION_ERROR", api_error_message, error_code=api_error_code)

    # Validate
    if not isinstance(workspace_id, str) or not re.match(r"^ais_wsp_[0-9A-Z]{10,}$", workspace_id):
        _log_request("jira_get_sprint_issues", workspace_id if isinstance(workspace_id, str) else "unknown", connection_id if isinstance(connection_id, str) else None,
                     {"workspace_id": workspace_id, "connection_id": connection_id, "sprint_id": sprint_id}, status="failed", http_status=400,
                     error_code="VALIDATION_ERROR", error_message="Invalid workspace_id.", started_at=now, finished_at=now)
        return _err("VALIDATION_ERROR", "Invalid workspace_id.")
    if not isinstance(connection_id, str) or not re.match(r"^ais_con_[0-9A-Z]{10,}$", connection_id):
        _log_request("jira_get_sprint_issues", workspace_id, connection_id if isinstance(connection_id, str) else None,
                     {"workspace_id": workspace_id, "connection_id": connection_id, "sprint_id": sprint_id}, status="failed", http_status=400,
                     error_code="VALIDATION_ERROR", error_message="Invalid connection_id.", started_at=now, finished_at=now)
        return _err("VALIDATION_ERROR", "Invalid connection_id.")
    if not isinstance(sprint_id, str) or not sprint_id.strip():
        return _err("VALIDATION_ERROR", "sprint_id must be a non-empty string.")
    if fields is not None and not isinstance(fields, str):
        return _err("VALIDATION_ERROR", "fields must be a string.")
    if start_at is not None and (not isinstance(start_at, int) or start_at < 0):
        return _err("VALIDATION_ERROR", "start_at must be an integer >= 0.")
    if limit is not None and (not isinstance(limit, int) or limit < 1):
        return _err("VALIDATION_ERROR", "limit must be an integer >= 1.")
    if refresh is not None and not isinstance(refresh, bool):
        return _err("VALIDATION_ERROR", "refresh must be a boolean.")

    workspaces = _load("workspaces.json")
    wsp = next((w for w in workspaces if w.get("workspace_id") == workspace_id), None)
    if not wsp:
        _log_request("jira_get_sprint_issues", workspace_id, connection_id, {"sprint_id": sprint_id}, status="failed", http_status=404,
                     error_code="NOT_FOUND", error_message="Workspace not found.", started_at=now, finished_at=now)
        return _err("NOT_FOUND", "Workspace not found.")
    if wsp.get("status") != "active":
        params = {"sprint_id": sprint_id, "fields": fields, "start_at": start_at, "limit": limit, "refresh": refresh}
        return _reject("WORKSPACE_INACTIVE", "Workspace is not active.", params, http_status=403)

    dps = wsp.get("default_page_size", 25)
    mps = wsp.get("max_page_size", 200)
    if not isinstance(dps, int) or dps < 1:
        dps = 25
    if not isinstance(mps, int) or mps < 1:
        mps = 200
    if start_at is None:
        start_at = 0
    if limit is None:
        limit = dps
    if limit < 1 or limit > mps:
        params = {"sprint_id": sprint_id, "fields": fields, "start_at": start_at, "limit": limit, "refresh": refresh}
        _log_request("jira_get_sprint_issues", workspace_id, connection_id, params, status="failed", http_status=400,
                     error_code="VALIDATION_ERROR", error_message="limit out of range for workspace.", started_at=now, finished_at=now)
        return _err("VALIDATION_ERROR", f"limit must be between 1 and {mps}.")

    cons = _load("atlassian_connections.json")
    con = next((c for c in cons if c.get("connection_id") == connection_id and c.get("workspace_id") == workspace_id and c.get("product") == "jira"), None)
    if not con or con.get("status") != "active":
        params = {"sprint_id": sprint_id, "fields": fields, "start_at": start_at, "limit": limit, "refresh": refresh}
        return _reject("UPSTREAM_UNAVAILABLE", "No active Jira connection available for this workspace/connection.", params, http_status=503)

    started = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    if refresh is True:
        con["last_sync_at"] = started
        con["updated_at"] = started
        for i, c in enumerate(cons):
            if c.get("connection_id") == connection_id:
                cons[i] = con
                break
        _save("atlassian_connections.json", cons)

    entities = _load("jira_entities.json")

    # Sprint existence best-effort
    sprint_entity = next((e for e in entities if e.get("workspace_id") == workspace_id and e.get("connection_id") == connection_id and e.get("entity_type") == "sprint" and e.get("external_id") == sprint_id and e.get("status") == "active"), None)

    issues = [e for e in entities if e.get("workspace_id") == workspace_id and e.get("connection_id") == connection_id and e.get("entity_type") == "issue" and e.get("status") == "active"]

    # Sprint association heuristic: issue.json_payload.sprintId == sprint_id OR fields.sprint/id matches
    def _issue_in_sprint(e):
        jp = e.get("json_payload") if isinstance(e.get("json_payload"), dict) else {}
        if str(jp.get("sprintId")) == str(sprint_id):
            return True
        fields_obj = jp.get("fields")
        if isinstance(fields_obj, dict):
            v = fields_obj.get("sprint") or fields_obj.get("Sprint")  # best-effort
            if isinstance(v, dict):
                if str(v.get("id")) == str(sprint_id):
                    return True
            if isinstance(v, list):
                for it in v:
                    if isinstance(it, dict) and str(it.get("id")) == str(sprint_id):
                        return True
            # greenhopper custom field often list of sprint objects
            for _, val in fields_obj.items():
                if isinstance(val, list):
                    for it in val:
                        if isinstance(it, dict) and ("id" in it) and str(it.get("id")) == str(sprint_id):
                            return True
        return False

    if sprint_entity is not None:
        issues = [e for e in issues if _issue_in_sprint(e)]
    else:
        issues = []

    # Sort
    issues.sort(key=lambda e: ((e.get("external_key") or "").upper(), str(e.get("external_id") or "")))

    total = len(issues)
    page = issues[start_at:start_at + limit]
    has_more = (start_at + limit) < total

    wanted_fields = None
    if isinstance(fields, str) and fields.strip():
        wanted_fields = [f.strip() for f in fields.split(",") if f.strip()]

    def _project_issue_obj(e):
        jp = e.get("json_payload") if isinstance(e.get("json_payload"), dict) else {}
        obj = dict(jp) if jp else {}
        if "id" not in obj and e.get("external_id") is not None:
            obj["id"] = e.get("external_id")
        if "key" not in obj and e.get("external_key") is not None:
            obj["key"] = e.get("external_key")
        if "fields" in obj and isinstance(obj["fields"], dict) and wanted_fields is not None:
            filtered = {}
            for f in wanted_fields:
                if f in obj["fields"]:
                    filtered[f] = obj["fields"][f]
            if "summary" in obj["fields"]:
                filtered.setdefault("summary", obj["fields"]["summary"])
            obj["fields"] = filtered
        return obj

    issues_out = [_project_issue_obj(e) for e in page]
    affected = []
    if sprint_entity is not None:
        affected.append({"system": "jira", "entity_type": "sprint", "external_id": sprint_id})
    affected.extend([{"system": "jira", "entity_type": "issue", "external_id": e.get("external_id")} for e in page])

    result = {"startAt": start_at, "maxResults": limit, "total": total, "issues": issues_out, "sprintId": sprint_id}
    finished = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    _log_request(
        "jira_get_sprint_issues",
        workspace_id,
        connection_id,
        {"sprint_id": sprint_id, "fields": fields, "start_at": start_at, "limit": limit, "refresh": refresh},
        status="succeeded",
        http_status=200,
        error_code=None,
        error_message=None,
        result_json=result,
        affected_entities=affected,
        started_at=started,
        finished_at=finished,
    )

    return {"search_results": result, "has_more": has_more, "next_cursor": (start_at + limit) if has_more else None, "latency_ms": int((time.time() - t0) * 1000)}

def jira_get_link_types(workspace_id, connection_id, refresh=None, **_extra):
    import json, os, datetime, re, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0275000" if __import__("os").path.isdir("./environment_mix/0275000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_ulid(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ts = int(time.time() * 1000)
        out = []
        for _ in range(10):
            out.append(alphabet[ts % 32])
            ts //= 32
        for _ in range(16):
            out.append(random.choice(alphabet))
        return prefix + "".join(out)

    def _log_request(status, http_status=None, error_code=None, error_message=None, result_json=None, affected=None, conn_id=None, params=None):
        tool_requests = _load("tool_requests.json")
        req_id = _new_ulid("ais_req_")
        row = {
            "tool_request_id": req_id,
            "workspace_id": workspace_id,
            "connection_id": conn_id,
            "tool_name": "jira_get_link_types",
            "params_json": params if isinstance(params, dict) else {},
            "status": status,
            "http_status": http_status,
            "error_code": error_code,
            "error_message": error_message,
            "result_json": result_json,
            "affected_entities": affected,
            "started_at": now,
            "finished_at": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
            "created_at": now,
            "updated_at": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
        }
        tool_requests.append(row)
        _save("tool_requests.json", tool_requests)
        return row

    # Validate inputs
    if not isinstance(workspace_id, str) or not re.match(r"^ais_wsp_[0-9A-Z]{10,}$", workspace_id):
        _log_request("rejected", http_status=400, error_code="VALIDATION_ERROR", error_message="Invalid workspace_id.", conn_id=None,
                     params={"workspace_id": workspace_id, "connection_id": connection_id, "refresh": refresh})
        return _err("VALIDATION_ERROR", "Invalid workspace_id.")
    if not isinstance(connection_id, str) or not re.match(r"^ais_con_[0-9A-Z]{10,}$", connection_id):
        _log_request("rejected", http_status=400, error_code="VALIDATION_ERROR", error_message="Invalid connection_id.", conn_id=None,
                     params={"workspace_id": workspace_id, "connection_id": connection_id, "refresh": refresh})
        return _err("VALIDATION_ERROR", "Invalid connection_id.")
    if refresh is not None and not isinstance(refresh, bool):
        _log_request("rejected", http_status=400, error_code="VALIDATION_ERROR", error_message="refresh must be boolean.", conn_id=connection_id,
                     params={"workspace_id": workspace_id, "connection_id": connection_id, "refresh": refresh})
        return _err("VALIDATION_ERROR", "refresh must be boolean.")

    workspaces = _load("workspaces.json")
    ws = next((w for w in workspaces if w.get("workspace_id") == workspace_id), None)
    if not ws:
        _log_request("failed", http_status=404, error_code="NOT_FOUND", error_message="Workspace not found.", conn_id=None,
                     params={"workspace_id": workspace_id, "connection_id": connection_id, "refresh": refresh})
        return _err("NOT_FOUND", "Workspace not found.")
    if ws.get("status") != "active":
        _log_request("rejected", http_status=403, error_code="WORKSPACE_INACTIVE", error_message="Workspace is not active.", conn_id=None,
                     params={"workspace_id": workspace_id, "connection_id": connection_id, "refresh": refresh})
        return _err("UNAUTHORIZED", "Workspace is not active.", error_code="WORKSPACE_INACTIVE")

    conns = _load("atlassian_connections.json")
    conn = next((c for c in conns if c.get("connection_id") == connection_id), None)
    if not conn:
        _log_request("failed", http_status=404, error_code="NOT_FOUND", error_message="Connection not found.", conn_id=None,
                     params={"workspace_id": workspace_id, "connection_id": connection_id, "refresh": refresh})
        return _err("NOT_FOUND", "Connection not found.")
    if conn.get("workspace_id") != workspace_id or conn.get("product") != "jira":
        _log_request("rejected", http_status=401, error_code="UNAUTHORIZED", error_message="Connection not accessible or not a Jira connection.", conn_id=connection_id,
                     params={"workspace_id": workspace_id, "connection_id": connection_id, "refresh": refresh})
        return _err("UNAUTHORIZED", "Connection not accessible or not a Jira connection.")
    if conn.get("status") != "active":
        _log_request("failed", http_status=503, error_code="UPSTREAM_UNAVAILABLE", error_message="Jira connection not active.", conn_id=connection_id,
                     params={"workspace_id": workspace_id, "connection_id": connection_id, "refresh": refresh})
        return _err("CONFLICT", "Jira connection not active.", error_code="UPSTREAM_UNAVAILABLE")

    jira_entities = _load("jira_entities.json")

    # "Refresh" in this offline server: mark fetched_at/updated_at now if any link types exist; otherwise cannot fetch upstream
    link_types = [e for e in jira_entities
                  if e.get("workspace_id") == workspace_id
                  and e.get("connection_id") == connection_id
                  and e.get("entity_type") == "link_type"
                  and e.get("status") == "active"]

    if refresh:
        if not link_types:
            _log_request("failed", http_status=501, error_code="NOT_IMPLEMENTED",
                         error_message="Upstream refresh is not available in offline datastore; no cached link types to return.",
                         conn_id=connection_id,
                         params={"workspace_id": workspace_id, "connection_id": connection_id, "refresh": True})
            return _err("CONFLICT", "Cannot refresh link types offline; cache is empty.", error_code="NOT_IMPLEMENTED")
        changed = 0
        for e in jira_entities:
            if (e.get("workspace_id") == workspace_id and e.get("connection_id") == connection_id and
                    e.get("entity_type") == "link_type" and e.get("status") == "active"):
                e["fetched_at"] = now
                e["updated_at"] = now
                changed += 1
        if changed:
            _save("jira_entities.json", jira_entities)
        link_types = [e for e in jira_entities
                      if e.get("workspace_id") == workspace_id
                      and e.get("connection_id") == connection_id
                      and e.get("entity_type") == "link_type"
                      and e.get("status") == "active"]

    result = [{
        "jira_entity_id": e.get("jira_entity_id"),
        "external_id": e.get("external_id"),
        "title": e.get("title"),
        "json_payload": e.get("json_payload"),
        "fetched_at": e.get("fetched_at"),
        "updated_at": e.get("updated_at"),
    } for e in link_types]

    _log_request(
        "succeeded",
        http_status=200,
        conn_id=connection_id,
        params={"workspace_id": workspace_id, "connection_id": connection_id, "refresh": bool(refresh)},
        result_json={"link_types": result, "count": len(result)},
        affected=[{"system": "jira", "entity_type": "link_type", "external_id": e.get("external_id")} for e in link_types] if link_types else []
    )
    return {"link_types": result, "count": len(result), "latency_ms": int((time.time() - t0) * 1000)}

