    def _log_request(status, http_status=None, error_code=None, error_message=None, result_json=None, affected=None):
        tr = {
            "tool_request_id": _new_id("ais_trq"),
            "workspace_id": workspace_id,
            "connection_id": connection_id,
            "tool_name": "jira_delete_issue",
            "params_json": {"issue_key": issue_key},
            "status": status,
            "http_status": http_status,
            "error_code": error_code,
