            "created_at": now,
            "updated_at": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
        }
        reqs.append(tr)
        _save("tool_requests.json", reqs)

    # Validate inputs
    if not (isinstance(workspace_id, str) and workspace_id.strip()):
        _log("rejected", http_status=400, error_code="VALIDATION_ERROR", error_message="workspace_id must be a non-empty string")
        return _err("VALIDATION_ERROR", "workspace_id must be a non-empty string")
    if not (isinstance(connection_id, str) and connection_id.strip()):
        _log("rejected", http_status=400, error_code="VALIDATION_ERROR", error_message="connection_id must be a non-empty string")
        return _err("VALIDATION_ERROR", "connection_id must be a non-empty string")
    if not (isinstance(issue_key, str) and issue_key.strip()):
        _log("rejected", http_status=400, error_code="VALIDATION_ERROR", error_message="issue_key must be a non-empty string")
        return _err("VALIDATION_ERROR", "issue_key must be a non-empty string")
    if not (isinstance(epic_key, str) and epic_key.strip()):
        _log("rejected", http_status=400, error_code="VALIDATION_ERROR", error_message="epic_key must be a non-empty string")
        return _err("VALIDATION_ERROR", "epic_key must be a non-empty string")

    # Resolve workspace
    wsp = next((w for w in workspaces if w.get("workspace_id") == workspace_id), None)
    if not wsp:
        _log("failed", http_status=404, error_code="NOT_FOUND", error_message="Workspace not found")
        return _err("NOT_FOUND", "Workspace not found")
    if wsp.get("status") != "active":
        _log("rejected", http_status=403, error_code="WORKSPACE_INACTIVE", error_message="Workspace is not active")
        return _err("UNAUTHORIZED", "Workspace is not active", error_code="WORKSPACE_INACTIVE")
    if wsp.get("read_only_mode") is True:
        _log("rejected", http_status=403, error_code="READ_ONLY_MODE", error_message="Workspace is in read-only mode")
        return _err("UNAUTHORIZED", "Workspace is in read-only mode", error_code="READ_ONLY_MODE")

    # Resolve connection must be Jira and active and match workspace
    conn = next((c for c in conns if c.get("connection_id") == connection_id and c.get("workspace_id") == workspace_id and c.get("product") == "jira"), None)
    if not conn:
        _log("failed", http_status=404, error_code="NOT_FOUND", error_message="Jira connection not found")
        return _err("NOT_FOUND", "Jira connection not found")
    if conn.get("status") != "active":
        _log("failed", http_status=503, error_code="UPSTREAM_UNAVAILABLE", error_message="Jira connection is not active")
        return _err("UNAUTHORIZED", "Jira connection unavailable", error_code="UPSTREAM_UNAVAILABLE")

    _log("running", http_status=102, result_json=None)

    # Find issue and epic in cache by external_key
    issue_row = next((e for e in jira if e.get("workspace_id") == workspace_id and e.get("connection_id") == connection_id and e.get("entity_type") == "issue" and e.get("external_key") == issue_key), None)
    if not issue_row:
        _log("failed", http_status=404, error_code="NOT_FOUND", error_message="Issue not found in cache")
        return _err("NOT_FOUND", "Issue not found")
    epic_row = next((e for e in jira if e.get("workspace_id") == workspace_id and e.get("connection_id") == connection_id and e.get("entity_type") == "issue" and e.get("external_key") == epic_key), None)
    if not epic_row:
        _log("failed", http_status=404, error_code="NOT_FOUND", error_message="Epic not found in cache")
        return _err("NOT_FOUND", "Epic not found")

    if issue_row.get("status") != "active":
        _log("failed", http_status=409, error_code="INVALID_TRANSITION", error_message="Issue is not active")
        return _err("INVALID_TRANSITION", "Issue is not active")
    if epic_row.get("status") != "active":
        _log("failed", http_status=409, error_code="INVALID_TRANSITION", error_message="Epic is not active")
        return _err("INVALID_TRANSITION", "Epic is not active")

    # Mutate issue payload to reflect epic link (best-effort local model)
    payload = issue_row.get("json_payload")
    if not isinstance(payload, dict):
        _log("failed", http_status=500, error_code="INVALID_JSON", error_message="Cached issue json_payload is invalid")
        return _err("CONFLICT", "Cached issue json_payload is invalid", error_code="INVALID_JSON")

    fields_obj = payload.get("fields")
    if not isinstance(fields_obj, dict):
        fields_obj = {}
        payload["fields"] = fields_obj

    # Use common Jira field naming; store both to increase compatibility
    epic_ref = {"key": epic_key, "id": epic_row.get("external_id")}
    fields_obj["epic"] = epic_ref
    fields_obj["customfield_epic_link"] = epic_key

    issue_row["json_payload"] = payload
    issue_row["updated_at"] = now
    issue_row["fetched_at"] = now

    _save("jira_entities.json", jira)

    affected = [
        {"system": "jira", "entity_type": "issue", "external_id": issue_row.get("external_id")},
        {"system": "jira", "entity_type": "issue", "external_id": epic_row.get("external_id")},
    ]
    result = payload

    _log("succeeded", http_status=200, result_json=result, affected=affected)
    return {
        "issue": result,
        "workspace_id": workspace_id,
        "connection_id": connection_id,
        "latency_ms": int((time.time() - t0) * 1000),
    }

