            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    tool_name = "jira_transition_issue"

    workspaces = _load("workspaces.json")
    conns = _load("atlassian_connections.json")
    jira = _load("jira_entities.json")
    reqs = _load("tool_requests.json")

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex[:22]}"

    def _log(status, http_status=None, error_code=None, error_message=None, result_json=None, affected=None):
        tr = {
            "tool_request_id": _new_id("ais_trq"),
            "workspace_id": workspace_id if isinstance(workspace_id, str) else "",
            "connection_id": connection_id if isinstance(connection_id, str) else None,
            "tool_name": tool_name,
            "params_json": {
                "issue_key": issue_key,
                "transition_id": transition_id,
                "fields": fields,
                "comment": comment,
            },
            "status": status,
            "http_status": http_status,
            "error_code": error_code,
            "error_message": error_message,
            "result_json": result_json,
            "affected_entities": affected,
            "started_at": now,
            "finished_at": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
            "created_at": now,
            "updated_at": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
        }
        reqs.append(tr)
        _save("tool_requests.json", reqs)

    # Validate
    for k, v in [("workspace_id", workspace_id), ("connection_id", connection_id), ("issue_key", issue_key), ("transition_id", transition_id)]:
        if not (isinstance(v, str) and v.strip()):
            _log("rejected", http_status=400, error_code="VALIDATION_ERROR", error_message=f"{k} must be a non-empty string")
            return _err("VALIDATION_ERROR", f"{k} must be a non-empty string")
    if fields is not None and not isinstance(fields, dict):
        _log("rejected", http_status=400, error_code="VALIDATION_ERROR", error_message="fields must be an object when provided")
        return _err("VALIDATION_ERROR", "fields must be an object when provided")
    if comment is not None and not isinstance(comment, str):
        _log("rejected", http_status=400, error_code="VALIDATION_ERROR", error_message="comment must be a string when provided")
        return _err("VALIDATION_ERROR", "comment must be a string when provided")

    # Workspace checks
    wsp = next((w for w in workspaces if w.get("workspace_id") == workspace_id), None)
    if not wsp:
        _log("failed", http_status=404, error_code="NOT_FOUND", error_message="Workspace not found")
        return _err("NOT_FOUND", "Workspace not found")
    if wsp.get("status") != "active":
        _log("rejected", http_status=403, error_code="WORKSPACE_INACTIVE", error_message="Workspace is not active")
        return _err("UNAUTHORIZED", "Workspace is not active", error_code="WORKSPACE_INACTIVE")
    if wsp.get("read_only_mode") is True:
        _log("rejected", http_status=403, error_code="READ_ONLY_MODE", error_message="Workspace is in read-only mode")
        return _err("UNAUTHORIZED", "Workspace is in read-only mode", error_code="READ_ONLY_MODE")

    # Connection checks
    conn = next((c for c in conns if c.get("connection_id") == connection_id and c.get("workspace_id") == workspace_id and c.get("product") == "jira"), None)
    if not conn:
        _log("failed", http_status=404, error_code="NOT_FOUND", error_message="Jira connection not found")
        return _err("NOT_FOUND", "Jira connection not found")
    if conn.get("status") != "active":
        _log("failed", http_status=503, error_code="UPSTREAM_UNAVAILABLE", error_message="Jira connection is not active")
        return _err("UNAUTHORIZED", "Jira connection unavailable", error_code="UPSTREAM_UNAVAILABLE")

    _log("running", http_status=102)

    issue = next((e for e in jira if e.get("workspace_id") == workspace_id and e.get("connection_id") == connection_id and e.get("entity_type") == "issue" and e.get("external_key") == issue_key), None)
    if not issue:
        _log("failed", http_status=404, error_code="NOT_FOUND", error_message="Issue not found")
        return _err("NOT_FOUND", "Issue not found")
    if issue.get("status") != "active":
        _log("failed", http_status=409, error_code="INVALID_TRANSITION", error_message="Issue is not active")
        return _err("INVALID_TRANSITION", "Issue is not active")

    payload = issue.get("json_payload")
    if not isinstance(payload, dict):
        _log("failed", http_status=500, error_code="INVALID_JSON", error_message="Cached issue json_payload is invalid")
        return _err("CONFLICT", "Cached issue json_payload is invalid", error_code="INVALID_JSON")

    # Validate transition exists in latest transitions list inside payload
    transitions = None
    if isinstance(payload.get("transitions"), list):
        transitions = payload.get("transitions")
    elif isinstance(payload.get("fields"), dict) and isinstance(payload["fields"].get("transitions"), list):
        transitions = payload["fields"].get("transitions")

    valid_ids = set()
    if isinstance(transitions, list):
        for tr in transitions:
            if isinstance(tr, dict):
                tid = tr.get("id")
                if tid is not None:
                    valid_ids.add(str(tid))

    if str(transition_id) not in valid_ids:
        _log("failed", http_status=409, error_code="INVALID_TRANSITION", error_message="transition_id not valid for issue")
        return _err("INVALID_TRANSITION", "Invalid transition_id for issue", error_code="INVALID_TRANSITION")

    # Apply updates locally
    fields_obj = payload.get("fields")
    if not isinstance(fields_obj, dict):
        fields_obj = {}
        payload["fields"] = fields_obj

    if isinstance(fields, dict):
        # Merge shallow
        for k, v in fields.items():
            fields_obj[k] = v

    # Update status if transition provides a 'to' name
    to_status = None
    for tr in (transitions or []):
        if isinstance(tr, dict) and str(tr.get("id")) == str(transition_id):
            to = tr.get("to")
            if isinstance(to, dict):
                to_status = to.get("name") or to.get("statusCategory", {}).get("name") if isinstance(to.get("statusCategory"), dict) else None
            break
    if to_status:
        fields_obj["status"] = {"name": to_status}

    # Append comment to payload history-like area
    if comment:
        hist = payload.get("comments")
        if not isinstance(hist, list):
            hist = []
            payload["comments"] = hist
        hist.append({"body": comment, "created": now, "transition_id": str(transition_id)})

    payload["last_transition"] = {"id": str(transition_id), "at": now}
    issue["json_payload"] = payload
    issue["updated_at"] = now
    issue["fetched_at"] = now
    _save("jira_entities.json", jira)

    affected = [{"system": "jira", "entity_type": "issue", "external_id": issue.get("external_id")}]
    _log("succeeded", http_status=200, result_json=payload, affected=affected)

    return {
        "issue": payload,
        "workspace_id": workspace_id,
        "connection_id": connection_id,
        "latency_ms": int((time.time() - t0) * 1000),
    }

def jira_create_sprint(workspace_id, connection_id, board_id, sprint_name, start_date, end_date, goal=None, **_extra):
    import json, os, datetime, time, re, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0275000" if __import__("os").path.isdir("./environment_mix/0275000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    tool_name = "jira_create_sprint"
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix): return f"{prefix}{uuid.uuid4().hex[:26].upper()}"

    def _parse_iso(s, field):
        if not isinstance(s, str) or not s:
            return ("INVALID", f"{field} must be a non-empty ISO-8601 datetime string.")
        try:
            datetime.datetime.fromisoformat(s[:-1] if s.endswith("Z") else s)
            return (s, None)
        except Exception:
            return ("INVALID", f"{field} must be a valid ISO-8601 datetime string.")

    def _append_tool_request(status, http_status=None, error_code=None, error_message=None, result_json=None, affected_entities=None, started_at=None, finished_at=None, conn_for_log=None):
        trs = _load("tool_requests.json")
        row = {
            "tool_request_id": _new_id("ais_trq_"),
            "workspace_id": workspace_id if isinstance(workspace_id, str) else "unknown",
            "connection_id": conn_for_log,
            "tool_name": tool_name,
            "params_json": {
                "workspace_id": workspace_id,
                "connection_id": connection_id,
                "board_id": board_id,
                "sprint_name": sprint_name,
                "start_date": start_date,
                "end_date": end_date,
                "goal": goal,
            },
            "status": status,
            "http_status": http_status,
            "error_code": error_code,
            "error_message": error_message,
            "result_json": result_json,
            "affected_entities": affected_entities,
            "started_at": started_at,
            "finished_at": finished_at,
            "created_at": now,
            "updated_at": now,
        }
        trs.append(row)
        _save("tool_requests.json", trs)
        return row

    # Validate inputs (relax to accept schema; only enforce obvious types/pattern where provided)
    if not isinstance(workspace_id, str) or not re.match(r"^ais_wsp_[0-9A-Z]{10,}$", workspace_id):
        _append_tool_request("rejected", http_status=400, error_code="VALIDATION_ERROR", error_message="workspace_id must be a valid ais_wsp_... identifier.", started_at=now, finished_at=now, conn_for_log=connection_id if isinstance(connection_id, str) else None)
        return _err("VALIDATION_ERROR", "workspace_id must be a valid ais_wsp_... identifier.", error_code="VALIDATION_ERROR")
    if not isinstance(connection_id, str) or not re.match(r"^ais_con_[0-9A-Z]{10,}$", connection_id):
        _append_tool_request("rejected", http_status=400, error_code="VALIDATION_ERROR", error_message="connection_id must be a valid ais_con_... identifier.", started_at=now, finished_at=now, conn_for_log=None)
        return _err("VALIDATION_ERROR", "connection_id must be a valid ais_con_... identifier.", error_code="VALIDATION_ERROR")
    if not isinstance(board_id, str) or not board_id:
        _append_tool_request("rejected", http_status=400, error_code="VALIDATION_ERROR", error_message="board_id must be a non-empty string.", started_at=now, finished_at=now, conn_for_log=connection_id)
        return _err("VALIDATION_ERROR", "board_id must be a non-empty string.", error_code="VALIDATION_ERROR")
    if not isinstance(sprint_name, str) or not sprint_name:
        _append_tool_request("rejected", http_status=400, error_code="VALIDATION_ERROR", error_message="sprint_name must be a non-empty string.", started_at=now, finished_at=now, conn_for_log=connection_id)
        return _err("VALIDATION_ERROR", "sprint_name must be a non-empty string.", error_code="VALIDATION_ERROR")
    sd, sd_err = _parse_iso(start_date, "start_date")
    if sd_err:
        _append_tool_request("rejected", http_status=400, error_code="VALIDATION_ERROR", error_message=sd_err, started_at=now, finished_at=now, conn_for_log=connection_id)
        return _err("VALIDATION_ERROR", sd_err, error_code="VALIDATION_ERROR")
    ed, ed_err = _parse_iso(end_date, "end_date")
    if ed_err:
        _append_tool_request("rejected", http_status=400, error_code="VALIDATION_ERROR", error_message=ed_err, started_at=now, finished_at=now, conn_for_log=connection_id)
        return _err("VALIDATION_ERROR", ed_err, error_code="VALIDATION_ERROR")
    if goal is not None and not isinstance(goal, str):
        _append_tool_request("rejected", http_status=400, error_code="VALIDATION_ERROR", error_message="goal must be a string when provided.", started_at=now, finished_at=now, conn_for_log=connection_id)
        return _err("VALIDATION_ERROR", "goal must be a string when provided.", error_code="VALIDATION_ERROR")

    # Resolve workspace
    workspaces = _load("workspaces.json")
    ws = next((w for w in workspaces if w.get("workspace_id") == workspace_id), None)
    if not ws:
        _append_tool_request("failed", http_status=404, error_code="NOT_FOUND", error_message="Workspace not found.", started_at=now, finished_at=now, conn_for_log=connection_id)
        return _err("NOT_FOUND", "Workspace not found.", error_code="NOT_FOUND")
    if ws.get("status") != "active":
        _append_tool_request("rejected", http_status=403, error_code="WORKSPACE_INACTIVE", error_message="Workspace is not active.", started_at=now, finished_at=now, conn_for_log=connection_id)
        return _err("UNAUTHORIZED", "Workspace is not active.", error_code="WORKSPACE_INACTIVE")
    if ws.get("read_only_mode") is True:
        _append_tool_request("rejected", http_status=403, error_code="READ_ONLY_MODE", error_message="Workspace is in read-only mode.", started_at=now, finished_at=now, conn_for_log=connection_id)
        return _err("UNAUTHORIZED", "Workspace is in read-only mode.", error_code="READ_ONLY_MODE")

    # Resolve active Jira connection (fallback allowed)
    conns = _load("atlassian_connections.json")
    conn = next((c for c in conns if c.get("connection_id") == connection_id and c.get("workspace_id") == workspace_id and c.get("product") == "jira" and c.get("status") == "active"), None)
    if not conn:
        conn = next((c for c in conns if c.get("workspace_id") == workspace_id and c.get("product") == "jira" and c.get("status") == "active"), None)
    if not conn:
        _append_tool_request("failed", http_status=503, error_code="UPSTREAM_UNAVAILABLE", error_message="No active Jira connection available for workspace.", started_at=now, finished_at=now, conn_for_log=connection_id)
        return _err("UNAUTHORIZED", "No active Jira connection available for workspace.", error_code="UPSTREAM_UNAVAILABLE")

    jira_entities = _load("jira_entities.json")

    # Idempotency: if sprint exists on same board with same name and dates, return it
    existing = next((e for e in jira_entities if e.get("workspace_id") == workspace_id and e.get("connection_id") == conn.get("connection_id") and e.get("entity_type") == "sprint" and e.get("status") == "active" and (e.get("title") == sprint_name) and e.get("json_payload", {}).get("boardId") == board_id and e.get("json_payload", {}).get("startDate") == start_date and e.get("json_payload", {}).get("endDate") == end_date), None)
    if existing:
        payload = existing.get("json_payload") or {}
        _append_tool_request("succeeded", http_status=200, result_json=payload, affected_entities=[{"system": "jira", "entity_type": "sprint", "external_id": existing.get("external_id")}], started_at=now, finished_at=datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z", conn_for_log=conn.get("connection_id"))
        return payload

    sprint_external_id = f"s_{uuid.uuid4().hex[:10]}"
    payload = {
        "id": sprint_external_id,
        "name": sprint_name,
        "boardId": board_id,
        "startDate": start_date,
        "endDate": end_date,
        "goal": goal,
        "state": "future",
        "created": now,
    }
    row = {
        "jira_entity_id": _new_id("ais_jre_"),
        "workspace_id": workspace_id,
        "connection_id": conn.get("connection_id"),
        "entity_type": "sprint",
        "external_id": sprint_external_id,
        "external_key": None,
        "parent_external_id": board_id,
        "status": "active",
        "title": sprint_name,
        "body": goal,
        "json_payload": payload,
        "indexed_text": " ".join([sprint_name, goal or "", board_id]).strip(),
        "fetched_at": now,
        "created_at": now,
        "updated_at": now,
    }
    jira_entities.append(row)
    _save("jira_entities.json", jira_entities)

    _append_tool_request("succeeded", http_status=200, result_json=payload, affected_entities=[{"system": "jira", "entity_type": "sprint", "external_id": sprint_external_id}], started_at=now, finished_at=datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z", conn_for_log=conn.get("connection_id"))
    return payload

def jira_update_sprint(workspace_id, connection_id, sprint_id, sprint_name=None, state=None, start_date=None, end_date=None, goal=None, **_extra):
    import json, os, datetime, time, re, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0275000" if __import__("os").path.isdir("./environment_mix/0275000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    tool_requests = _load("tool_requests.json")
    workspaces = _load("workspaces.json")
    connections = _load("atlassian_connections.json")
    jira_entities = _load("jira_entities.json")

    def _new_id(prefix):
        return f"{prefix}{uuid.uuid4().hex[:26].upper()}"

    def _log(status, http_status=None, error_code=None, error_message=None, result_json=None, affected_entities=None, started_at=None, finished_at=None):
        tr = {
            "tool_request_id": _new_id("ais_req_"),
            "workspace_id": workspace_id if isinstance(workspace_id, str) else "ais_wsp_UNKNOWN",
            "connection_id": connection_id if isinstance(connection_id, str) else None,
            "tool_name": "jira_update_sprint",
            "params_json": {
                "sprint_id": sprint_id,
                "sprint_name": sprint_name,
                "state": state,
                "start_date": start_date,
                "end_date": end_date,
                "goal": goal
            },
            "status": status,
            "http_status": http_status,
            "error_code": error_code,
            "error_message": error_message,
            "result_json": result_json,
            "affected_entities": affected_entities,
            "started_at": started_at,
            "finished_at": finished_at,
            "created_at": now,
            "updated_at": now
        }
        tool_requests.append(tr)
        _save("tool_requests.json", tool_requests)
        return tr

    # Validate
    if not isinstance(workspace_id, str) or not re.match(r"^ais_wsp_[0-9A-Z]{10,}$", workspace_id):
        _log("rejected", http_status=400, error_code="VALIDATION_ERROR", error_message="Invalid workspace_id.")
        return _err("VALIDATION_ERROR", "Invalid workspace_id.")
    if not isinstance(connection_id, str) or not re.match(r"^ais_con_[0-9A-Z]{10,}$", connection_id):
        _log("rejected", http_status=400, error_code="VALIDATION_ERROR", error_message="Invalid connection_id.")
        return _err("VALIDATION_ERROR", "Invalid connection_id.")
    if not isinstance(sprint_id, str) or not sprint_id.strip():
        _log("rejected", http_status=400, error_code="VALIDATION_ERROR", error_message="sprint_id is required.")
        return _err("VALIDATION_ERROR", "sprint_id is required.")
    if sprint_name is not None and (not isinstance(sprint_name, str) or not sprint_name.strip()):
        _log("rejected", http_status=400, error_code="VALIDATION_ERROR", error_message="sprint_name must be a non-empty string when provided.")
        return _err("VALIDATION_ERROR", "sprint_name must be a non-empty string when provided.")
    if state is not None and state not in ("future", "active", "closed"):
        _log("rejected", http_status=400, error_code="VALIDATION_ERROR", error_message="Invalid state.")
        return _err("VALIDATION_ERROR", "Invalid state.")
    if goal is not None and not isinstance(goal, str):
        _log("rejected", http_status=400, error_code="VALIDATION_ERROR", error_message="goal must be a string.")
        return _err("VALIDATION_ERROR", "goal must be a string.")

    def _parse_dt_opt(x, field):
        if x is None:
            return None, None
        if not isinstance(x, str) or not x.strip():
            return None, _err("VALIDATION_ERROR", f"{field} must be an ISO-8601 date-time string.")
        s = x.strip()
        try:
            if s.endswith("Z"):
                dt = datetime.datetime.fromisoformat(s[:-1])
            else:
                dt = datetime.datetime.fromisoformat(s)
            return dt, None
        except ValueError:
            return None, _err("VALIDATION_ERROR", f"{field} must be an ISO-8601 date-time string.")

    sd, e1 = _parse_dt_opt(start_date, "start_date")
    if e1:
        _log("rejected", http_status=400, error_code="VALIDATION_ERROR", error_message=e1["error"]["message"])
        return e1
    ed, e2 = _parse_dt_opt(end_date, "end_date")
    if e2:
        _log("rejected", http_status=400, error_code="VALIDATION_ERROR", error_message=e2["error"]["message"])
        return e2
    if sd and ed and ed < sd:
        _log("rejected", http_status=400, error_code="VALIDATION_ERROR", error_message="end_date must be >= start_date.")
        return _err("VALIDATION_ERROR", "end_date must be >= start_date.")
    if all(v is None for v in (sprint_name, state, start_date, end_date, goal)):
        _log("rejected", http_status=400, error_code="VALIDATION_ERROR", error_message="At least one field must be provided to update.")
        return _err("VALIDATION_ERROR", "At least one field must be provided to update.")

    # Workspace checks
    wsp = next((w for w in workspaces if w.get("workspace_id") == workspace_id), None)
    if not wsp:
        _log("failed", http_status=404, error_code="NOT_FOUND", error_message="Workspace not found.")
        return _err("NOT_FOUND", "Workspace not found.")
    if wsp.get("status") != "active":
        _log("rejected", http_status=403, error_code="WORKSPACE_INACTIVE", error_message="Workspace is not active.")
        return _err("UNAUTHORIZED", "Workspace is not active.", error_code="WORKSPACE_INACTIVE")
    if wsp.get("read_only_mode") is True:
        _log("rejected", http_status=403, error_code="READ_ONLY_MODE", error_message="Workspace is in read-only mode.")
        return _err("UNAUTHORIZED", "Workspace is in read-only mode.", error_code="READ_ONLY_MODE")

    con = next((c for c in connections if c.get("connection_id") == connection_id and c.get("workspace_id") == workspace_id), None)
    if not con:
        _log("failed", http_status=401, error_code="UNAUTHORIZED", error_message="Connection is not accessible to workspace.")
        return _err("UNAUTHORIZED", "Connection is not accessible to workspace.")
    if con.get("product") != "jira":
        _log("failed", http_status=401, error_code="UNAUTHORIZED", error_message="Connection is not a Jira connection.")
        return _err("UNAUTHORIZED", "Connection is not a Jira connection.")
    if con.get("status") != "active":
        _log("failed", http_status=503, error_code="UPSTREAM_UNAVAILABLE", error_message="Jira connection is not active.")
        return _err("UNAUTHORIZED", "Jira connection unavailable.", error_code="UPSTREAM_UNAVAILABLE")

    started_at = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    tr = _log("running", started_at=started_at)

    # Find sprint
    sprint_row = next((e for e in jira_entities
                       if e.get("workspace_id") == workspace_id
                       and e.get("connection_id") == connection_id
                       and e.get("entity_type") == "sprint"
                       and str(e.get("external_id")) == str(sprint_id)), None)
    if not sprint_row or sprint_row.get("status") != "active":
        finished_at = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        tr["status"] = "failed"
        tr["http_status"] = 404
        tr["error_code"] = "NOT_FOUND"
        tr["error_message"] = "Sprint not found."
        tr["finished_at"] = finished_at
        tr["updated_at"] = now
        _save("tool_requests.json", tool_requests)
        return _err("NOT_FOUND", "Sprint not found.")

    # Enforce simple sprint state transitions
    current_state = (sprint_row.get("json_payload") or {}).get("state") or "future"
    if state is not None:
        allowed = {
            "future": {"active", "closed"},
            "active": {"closed"},
            "closed": set()
        }
        if state != current_state and state not in allowed.get(current_state, set()):
            finished_at = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            tr["status"] = "failed"
            tr["http_status"] = 409
            tr["error_code"] = "INVALID_TRANSITION"
            tr["error_message"] = f"Cannot transition sprint state from {current_state} to {state}."
            tr["finished_at"] = finished_at
            tr["updated_at"] = now
            _save("tool_requests.json", tool_requests)
            return _err("INVALID_TRANSITION", f"Cannot transition sprint state from {current_state} to {state}.")

    payload = sprint_row.get("json_payload") if isinstance(sprint_row.get("json_payload"), dict) else {}
    if not payload:
        payload = {"id": str(sprint_id)}

    if sprint_name is not None:
        payload["name"] = sprint_name
        sprint_row["title"] = sprint_name
    if state is not None:
        payload["state"] = state
    if start_date is not None:
        payload["startDate"] = start_date
    if end_date is not None:
        payload["endDate"] = end_date
    if goal is not None:
        payload["goal"] = goal

    sprint_row["json_payload"] = payload
    sprint_row["indexed_text"] = " ".join([x for x in [sprint_row.get("title"), payload.get("goal")] if isinstance(x, str) and x.strip()]) or sprint_row.get("indexed_text")
    sprint_row["fetched_at"] = now
    sprint_row["updated_at"] = now
    _save("jira_entities.json", jira_entities)

    finished_at = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    tr["status"] = "succeeded"
    tr["http_status"] = 200
    tr["result_json"] = payload
    tr["affected_entities"] = [{"system": "jira", "entity_type": "sprint", "external_id": str(sprint_id)}]
    tr["finished_at"] = finished_at
    tr["updated_at"] = now
    _save("tool_requests.json", tool_requests)

    return payload

def confluence_search(workspace_id, connection_id, query, limit=None, spaces_filter=None, **_extra):
    import json, os, datetime, uuid, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0275000" if __import__("os").path.isdir("./environment_mix/0275000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _new_id(prefix):
        return f"{prefix}{uuid.uuid4().hex[:26].upper()}"

    def _log(status, http_status=None, error_code=None, error_message=None, result_json=None, affected_entities=None, started_at=None, finished_at=None):
        trs = _load("tool_requests.json")
        row = {
            "tool_request_id": _new_id("ais_trq_"),
            "workspace_id": workspace_id if isinstance(workspace_id, str) else "unknown",
            "connection_id": connection_id if isinstance(connection_id, str) else None,
            "tool_name": "confluence_search",
            "params_json": {"query": query, "limit": limit, "spaces_filter": spaces_filter},
            "status": status,
            "http_status": http_status,
            "error_code": error_code,
            "error_message": error_message,
            "result_json": result_json,
            "affected_entities": affected_entities,
            "started_at": started_at,
            "finished_at": finished_at,
            "created_at": now,
            "updated_at": now
        }
        trs.append(row)
        _save("tool_requests.json", trs)
        return row

    def _check_limits():
        trs = _load("tool_requests.json")
        one_min_ago = (now_dt - datetime.timedelta(minutes=1)).isoformat() + "Z"
        day_ago = (now_dt - datetime.timedelta(days=1)).isoformat() + "Z"
        per_min = 0
        per_day = 0
        for r in trs:
            if r.get("workspace_id") != workspace_id:
                continue
            ca = r.get("created_at")
            if isinstance(ca, str) and ca >= one_min_ago:
                per_min += 1
            if isinstance(ca, str) and ca >= day_ago:
                per_day += 1
        if per_min >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded for workspace (120 requests/min).")
        if per_day >= 20000:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded for workspace (20000 requests/day).")
        return None

    # Validate
    if not isinstance(workspace_id, str) or not re.match(r"^ais_wsp_[0-9A-Z]{10,}$", workspace_id):
        _log("rejected", http_status=400, error_code="VALIDATION_ERROR", error_message="Invalid workspace_id.")
        return _err("VALIDATION_ERROR", "Invalid workspace_id.")
    if not isinstance(connection_id, str) or not re.match(r"^ais_con_[0-9A-Z]{10,}$", connection_id):
        _log("rejected", http_status=400, error_code="VALIDATION_ERROR", error_message="Invalid connection_id.")
        return _err("VALIDATION_ERROR", "Invalid connection_id.")
    if not isinstance(query, str) or not query.strip():
        _log("rejected", http_status=400, error_code="VALIDATION_ERROR", error_message="query must be a non-empty string.")
        return _err("VALIDATION_ERROR", "query must be a non-empty string.")
    if limit is not None and (not isinstance(limit, int) or limit < 1 or limit > 50):
        _log("rejected", http_status=400, error_code="VALIDATION_ERROR", error_message="limit must be an integer between 1 and 50.")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 50.")
    if spaces_filter is not None and not isinstance(spaces_filter, str):
        _log("rejected", http_status=400, error_code="VALIDATION_ERROR", error_message="spaces_filter must be a string when provided.")
        return _err("VALIDATION_ERROR", "spaces_filter must be a string when provided.")

    lim_err = _check_limits()
    if lim_err:
        _log("rejected", http_status=429, error_code=lim_err["error"]["code"], error_message=lim_err["error"]["message"])
        return lim_err

    started_at = now
    _log("running", started_at=started_at)

    workspaces = _load("workspaces.json")
    conns = _load("atlassian_connections.json")
    ents = _load("confluence_entities.json")

    ws = next((w for w in workspaces if w.get("workspace_id") == workspace_id), None)
    if not ws:
        _log("failed", http_status=404, error_code="NOT_FOUND", error_message="Workspace not found", started_at=started_at, finished_at=datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z")
        return _err("NOT_FOUND", "Workspace not found")
    if ws.get("status") != "active":
        _log("rejected", http_status=403, error_code="WORKSPACE_INACTIVE", error_message="Workspace is not active", started_at=started_at, finished_at=datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z")
        return _err("UNAUTHORIZED", "Workspace is not active", error_code="WORKSPACE_INACTIVE")

    conn = next((c for c in conns if c.get("connection_id") == connection_id), None)
    if not (conn and conn.get("workspace_id") == workspace_id and conn.get("product") == "confluence" and conn.get("status") == "active"):
        conn = next((c for c in conns if c.get("workspace_id") == workspace_id and c.get("product") == "confluence" and c.get("status") == "active"), None)
    if not conn:
        _log("failed", http_status=503, error_code="UPSTREAM_UNAVAILABLE", error_message="No active Confluence connection available for workspace", started_at=started_at, finished_at=datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z")
        return _err("UNAUTHORIZED", "No active Confluence connection available for workspace", error_code="UPSTREAM_UNAVAILABLE")
    connection_id = conn.get("connection_id")

    ws_limit_default = ws.get("default_page_size")
    ws_max = ws.get("max_page_size")
    if not isinstance(ws_limit_default, int) or ws_limit_default < 1:
        ws_limit_default = 20
    if not isinstance(ws_max, int) or ws_max < 1:
        ws_max = 200

    if limit is None:
        limit_eff = ws_limit_default
    else:
        limit_eff = limit
    # Confluence search additionally caps at 50
    cap = min(ws_max, 50)
    if limit_eff < 1 or limit_eff > cap:
        _log("rejected", http_status=400, error_code="VALIDATION_ERROR", error_message=f"limit must be between 1 and {cap}.", started_at=started_at, finished_at=datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z")
        return _err("VALIDATION_ERROR", f"limit must be between 1 and {cap}.")

    spaces = None
    if isinstance(spaces_filter, str) and spaces_filter.strip():
        spaces = [s.strip() for s in spaces_filter.split(",") if s.strip()]

    q = query.strip().lower()
    results = []
    affected = []
    for e in ents:
        if e.get("workspace_id") != workspace_id or e.get("connection_id") != connection_id:
            continue
        if e.get("entity_type") != "page":
            continue
        if e.get("status") != "current":
            continue
        if spaces and e.get("space_key") not in spaces:
            continue
        hay = " ".join([str(e.get("title") or ""), str(e.get("content") or ""), str(e.get("external_id") or "")]).lower()
        if q in hay:
            obj = {
                "id": e.get("external_id"),
                "title": e.get("title"),
                "space_key": e.get("space_key"),
                "status": e.get("status")
            }
            results.append(obj)
            affected.append({"system": "confluence", "entity_type": "page", "external_id": e.get("external_id")})
            if len(results) >= limit_eff:
                break

    finished_at = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    payload = {"results": results, "total": len(results), "limit": limit_eff}
    _log("succeeded", http_status=200, result_json=payload, affected_entities=affected, started_at=started_at, finished_at=finished_at)
    return payload

def confluence_get_page(workspace_id, connection_id, page_id, include_metadata=None, convert_to_markdown=None, **_extra):
    import json, os, datetime, time, uuid, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0275000" if __import__("os").path.isdir("./environment_mix/0275000") else "/app/database")
    def _load(n):
