    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    tool_name = "confluence_get_page"
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix): return f"{prefix}{uuid.uuid4().hex[:26].upper()}"

    def _append_tool_request(status, http_status=None, error_code=None, error_message=None, result_json=None, affected_entities=None, started_at=None, finished_at=None, conn_for_log=None):
        trs = _load("tool_requests.json")
        row = {
            "tool_request_id": _new_id("ais_trq_"),
            "workspace_id": workspace_id if isinstance(workspace_id, str) else "unknown",
            "connection_id": conn_for_log,
            "tool_name": tool_name,
            "params_json": {
                "workspace_id": workspace_id,
                "connection_id": connection_id,
                "page_id": page_id,
                "include_metadata": include_metadata,
                "convert_to_markdown": convert_to_markdown,
            },
            "status": status,
            "http_status": http_status,
            "error_code": error_code,
            "error_message": error_message,
            "result_json": result_json,
            "affected_entities": affected_entities,
            "started_at": started_at,
            "finished_at": finished_at,
            "created_at": now,
            "updated_at": now,
        }
        trs.append(row)
        _save("tool_requests.json", trs)
        return row

    if include_metadata is None: include_metadata = False
    if convert_to_markdown is None: convert_to_markdown = False

    # Validate inputs
    if not (isinstance(workspace_id, str) and re.match(r"^ais_wsp_[0-9A-Z]{10,}$", workspace_id)):
        _append_tool_request("rejected", http_status=400, error_code="VALIDATION_ERROR", error_message="workspace_id must be a valid ais_wsp_... identifier.", started_at=now, finished_at=now, conn_for_log=connection_id if isinstance(connection_id, str) else None)
        return _err("VALIDATION_ERROR", "workspace_id must be a valid ais_wsp_... identifier.", error_code="VALIDATION_ERROR")
    if not (isinstance(connection_id, str) and re.match(r"^ais_con_[0-9A-Z]{10,}$", connection_id)):
        _append_tool_request("rejected", http_status=400, error_code="VALIDATION_ERROR", error_message="connection_id must be a valid ais_con_... identifier.", started_at=now, finished_at=now)
        return _err("VALIDATION_ERROR", "connection_id must be a valid ais_con_... identifier.", error_code="VALIDATION_ERROR")
    if not isinstance(page_id, str) or not page_id:
        _append_tool_request("rejected", http_status=400, error_code="VALIDATION_ERROR", error_message="page_id must be a non-empty string.", started_at=now, finished_at=now, conn_for_log=connection_id)
        return _err("VALIDATION_ERROR", "page_id must be a non-empty string.", error_code="VALIDATION_ERROR")
    if not isinstance(include_metadata, bool):
        _append_tool_request("rejected", http_status=400, error_code="VALIDATION_ERROR", error_message="include_metadata must be a boolean.", started_at=now, finished_at=now, conn_for_log=connection_id)
        return _err("VALIDATION_ERROR", "include_metadata must be a boolean.", error_code="VALIDATION_ERROR")
    if not isinstance(convert_to_markdown, bool):
        _append_tool_request("rejected", http_status=400, error_code="VALIDATION_ERROR", error_message="convert_to_markdown must be a boolean.", started_at=now, finished_at=now, conn_for_log=connection_id)
        return _err("VALIDATION_ERROR", "convert_to_markdown must be a boolean.", error_code="VALIDATION_ERROR")

    # Resolve workspace
    workspaces = _load("workspaces.json")
    ws = next((w for w in workspaces if w.get("workspace_id") == workspace_id), None)
    if not ws:
        _append_tool_request("failed", http_status=404, error_code="NOT_FOUND", error_message="Workspace not found.", started_at=now, finished_at=now, conn_for_log=connection_id)
        return _err("NOT_FOUND", "Workspace not found.", error_code="NOT_FOUND")
    if ws.get("status") != "active":
        _append_tool_request("rejected", http_status=403, error_code="WORKSPACE_INACTIVE", error_message="Workspace is not active.", started_at=now, finished_at=now, conn_for_log=connection_id)
        return _err("UNAUTHORIZED", "Workspace is not active.", error_code="WORKSPACE_INACTIVE")

    # Resolve active Confluence connection (fallback allowed)
    conns = _load("atlassian_connections.json")
    conn = next((c for c in conns if c.get("connection_id") == connection_id and c.get("workspace_id") == workspace_id and c.get("product") == "confluence" and c.get("status") == "active"), None)
    if not conn:
        conn = next((c for c in conns if c.get("workspace_id") == workspace_id and c.get("product") == "confluence" and c.get("status") == "active"), None)
    if not conn:
        _append_tool_request("failed", http_status=503, error_code="UPSTREAM_UNAVAILABLE", error_message="No active Confluence connection available for workspace.", started_at=now, finished_at=now, conn_for_log=connection_id)
        return _err("UNAUTHORIZED", "No active Confluence connection available for workspace.", error_code="UPSTREAM_UNAVAILABLE")

    entities = _load("confluence_entities.json")
    page = next((e for e in entities if e.get("workspace_id") == workspace_id and e.get("connection_id") == conn.get("connection_id") and e.get("entity_type") == "page" and e.get("external_id") == page_id and e.get("status") == "current"), None)
    if not page:
        _append_tool_request("failed", http_status=404, error_code="NOT_FOUND", error_message="Page not found in cache.", started_at=now, finished_at=now, conn_for_log=conn.get("connection_id"))
        return _err("NOT_FOUND", "Page not found.", error_code="NOT_FOUND")

    desired_format = "markdown" if convert_to_markdown else "html"
    result = dict(page.get("json_payload") or {})
    result.update({
        "id": page.get("external_id"),
        "type": "page",
        "title": page.get("title"),
        "spaceKey": page.get("space_key"),
        "content_format": desired_format,
        "content": page.get("content"),
    })

    # Honor convert_to_markdown by persisting content_format (and leaving content as-is if already that format)
    changed = False
    if page.get("content_format") != desired_format:
        # naive "conversion": store same content but mark format; real service would convert upstream.
        page["content_format"] = desired_format
        page["updated_at"] = now
        page["fetched_at"] = now
        changed = True

    if include_metadata:
        result["metadata"] = page.get("metadata_json") or {}
    else:
        result.pop("metadata", None)

    if changed:
        _save("confluence_entities.json", entities)

    _append_tool_request("succeeded", http_status=200, result_json=result, affected_entities=[{"system": "confluence", "entity_type": "page", "external_id": page_id}], started_at=now, finished_at=datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z", conn_for_log=conn.get("connection_id"))
    return result

