        trs = _load("tool_requests.json")
        row = {
            "tool_request_id": _new_id("ais_trq_"),
            "workspace_id": workspace_id if isinstance(workspace_id, str) else "unknown",
            "connection_id": connection_id if isinstance(connection_id, str) else None,
            "tool_name": "confluence_create_page",
            "params_json": {"space_key": space_key, "title": title, "content": content, "parent_id": parent_id},
            "status": status,
            "http_status": http_status,
            "error_code": error_code,
            "error_message": error_message,
            "result_json": result_json,
            "affected_entities": affected_entities,
            "started_at": started_at,
            "finished_at": finished_at,
            "created_at": now,
            "updated_at": now
        }
        trs.append(row)
        _save("tool_requests.json", trs)
        return row

    def _check_limits():
        trs = _load("tool_requests.json")
        one_min_ago = (now_dt - datetime.timedelta(minutes=1)).isoformat() + "Z"
        day_ago = (now_dt - datetime.timedelta(days=1)).isoformat() + "Z"
        per_min = 0
        per_day = 0
        for r in trs:
            if r.get("workspace_id") != workspace_id:
                continue
            ca = r.get("created_at")
            if isinstance(ca, str) and ca >= one_min_ago:
                per_min += 1
            if isinstance(ca, str) and ca >= day_ago:
                per_day += 1
        if per_min >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded for workspace (120 requests/min).")
        if per_day >= 20000:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded for workspace (20000 requests/day).")
        return None

    # Validate
    if not isinstance(workspace_id, str) or not re.match(r"^ais_wsp_[0-9A-HJKMNP-TV-Z]{10,}$", workspace_id):
        _log("rejected", http_status=400, error_code="VALIDATION_ERROR", error_message="Invalid workspace_id.")
        return _err("VALIDATION_ERROR", "Invalid workspace_id.")
    if not isinstance(connection_id, str) or not re.match(r"^ais_con_[0-9A-HJKMNP-TV-Z]{10,}$", connection_id):
        _log("rejected", http_status=400, error_code="VALIDATION_ERROR", error_message="Invalid connection_id.")
        return _err("VALIDATION_ERROR", "Invalid connection_id.")
    if not isinstance(space_key, str) or not space_key.strip():
        _log("rejected", http_status=400, error_code="VALIDATION_ERROR", error_message="space_key is required.")
        return _err("VALIDATION_ERROR", "space_key is required.")
    if not isinstance(title, str) or not title.strip():
        _log("rejected", http_status=400, error_code="VALIDATION_ERROR", error_message="title is required.")
        return _err("VALIDATION_ERROR", "title is required.")
    if not isinstance(content, str):
        _log("rejected", http_status=400, error_code="VALIDATION_ERROR", error_message="content must be a string.")
        return _err("VALIDATION_ERROR", "content must be a string.")
    if parent_id is not None and (not isinstance(parent_id, str) or not parent_id.strip()):
        _log("rejected", http_status=400, error_code="VALIDATION_ERROR", error_message="parent_id must be a non-empty string when provided.")
        return _err("VALIDATION_ERROR", "parent_id must be a non-empty string when provided.")

    lim_err = _check_limits()
    if lim_err:
        _log("rejected", http_status=429, error_code=lim_err["error"]["code"], error_message=lim_err["error"]["message"])
        return lim_err

    started_at = now
    _log("running", started_at=started_at)

    workspaces = _load("workspaces.json")
