        conn = next((c for c in conns if c.get("workspace_id") == workspace_id and c.get("product") == "confluence" and c.get("status") == "active"), None)
    if not conn:
        _log("failed", http_status=503, error_code="UPSTREAM_UNAVAILABLE", error_message="No active Confluence connection available for workspace", started_at=started_at, finished_at=datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z")
        return _err("UNAUTHORIZED", "No active Confluence connection available for workspace", error_code="UPSTREAM_UNAVAILABLE")
    connection_id = conn.get("connection_id")

    # If parent_id provided, ensure it exists
    if parent_id is not None:
        parent = next((e for e in ents if e.get("workspace_id") == workspace_id and e.get("connection_id") == connection_id and e.get("entity_type") == "page" and e.get("external_id") == parent_id and e.get("status") == "current"), None)
