            return _err("NOT_FOUND", "Parent page not found")

    # Create new page entity (content is markdown per tool contract)
    page_external_id = str(uuid.uuid4().int % 10**12)
    payload = {
        "id": page_external_id,
        "type": "page",
        "space": {"key": space_key.strip()},
        "title": title.strip(),
        "ancestors": ([{"id": parent_id}] if parent_id else []),
        "body": {"storage": {"value": content, "representation": "markdown"}},
        "created": now,
        "updated": now
    }
    row = {
        "confluence_entity_id": _new_id("ais_conf_"),
        "workspace_id": workspace_id,
        "connection_id": connection_id,
        "entity_type": "page",
        "external_id": page_external_id,
