        "metadata_json": None,
        "fetched_at": now,
        "created_at": now,
        "updated_at": now
    }
    ents.append(row)
    _save("confluence_entities.json", ents)

    affected = [{"system": "confluence", "entity_type": "page", "external_id": page_external_id}]
    _log("succeeded", http_status=200, result_json=payload, affected_entities=affected, started_at=started_at, finished_at=datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z")
    return payload

