        _append_tool_request("rejected", http_status=403, error_code="READ_ONLY_MODE", error_message="Workspace is in read-only mode.", started_at=now, finished_at=now, conn_for_log=connection_id)
        return _err("UNAUTHORIZED", "Workspace is in read-only mode.", error_code="READ_ONLY_MODE")

    # Resolve active Confluence connection (fallback allowed)
    conns = _load("atlassian_connections.json")
    conn = next((c for c in conns if c.get("connection_id") == connection_id and c.get("workspace_id") == workspace_id and c.get("product") == "confluence" and c.get("status") == "active"), None)
    if not conn:
        conn = next((c for c in conns if c.get("workspace_id") == workspace_id and c.get("product") == "confluence" and c.get("status") == "active"), None)
    if not conn:
        _append_tool_request("failed", http_status=503, error_code="UPSTREAM_UNAVAILABLE", error_message="No active Confluence connection available for workspace.", started_at=now, finished_at=now, conn_for_log=connection_id)
        return _err("UNAUTHORIZED", "No active Confluence connection available for workspace.", error_code="UPSTREAM_UNAVAILABLE")

    entities = _load("confluence_entities.json")
    page = next((e for e in entities if e.get("workspace_id") == workspace_id and e.get("connection_id") == conn.get("connection_id") and e.get("entity_type") == "page" and e.get("external_id") == page_id), None)
    if not page or page.get("status") != "current":
        _append_tool_request("failed", http_status=404, error_code="NOT_FOUND", error_message="Page not found or not current.", started_at=now, finished_at=now, conn_for_log=conn.get("connection_id"))
