    page["content"] = content
    page["content_format"] = "markdown"  # tool says content is Markdown format
    if parent_id is not None:
        page["parent_external_id"] = parent_id
    # Update metadata_json with a simple version bump
    meta = page.get("metadata_json") if isinstance(page.get("metadata_json"), dict) else {}
    ver = meta.get("version") if isinstance(meta.get("version"), dict) else {}
    number = ver.get("number")
