    page["metadata_json"] = meta
    page["updated_at"] = now
    page["fetched_at"] = now

    _save("confluence_entities.json", entities)

    result = {
        "id": page_id,
        "type": "page",
        "title": title,
        "spaceKey": page.get("space_key"),
        "content_format": page.get("content_format"),
        "content": page.get("content"),
        "metadata": page.get("metadata_json"),
        "parent_id": page.get("parent_external_id"),
    }
    _append_tool_request("succeeded", http_status=200, result_json=result, affected_entities=[{"system": "confluence", "entity_type": "page", "external_id": page_id}], started_at=now, finished_at=datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z", conn_for_log=conn.get("connection_id"))
