    page["status"] = "deleted"
    page["updated_at"] = now
    page["fetched_at"] = now
    _save("confluence_entities.json", entities)

    result = {"id": page_id, "deleted": True, "status": "deleted"}
    _append_tool_request("succeeded", http_status=200, result_json=result, affected_entities=[{"system": "confluence", "entity_type": "page", "external_id": page_id}], started_at=now, finished_at=datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z", conn_for_log=conn.get("connection_id"))
    return result

def workspaces_list(status=None, limit=None, start_at=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0275000" if __import__("os").path.isdir("./environment_mix/0275000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    if status is not None:
        if not isinstance(status, str) or status not in ("active", "suspended", "deleted"):
            return _err("VALIDATION_ERROR", "Invalid status filter.")
    if limit is not None and (not isinstance(limit, int) or limit < 1):
        return _err("VALIDATION_ERROR", "limit must be an integer >= 1.")
    if start_at is not None and (not isinstance(start_at, int) or start_at < 0):
        return _err("VALIDATION_ERROR", "start_at must be an integer >= 0.")
    if start_at is None:
        start_at = 0

    workspaces = _load("workspaces.json")
    # Choose a "caller workspace default" when applicable: use any active workspace's defaults, else fall back.
    active_ws = next((w for w in workspaces if w.get("status") == "active" and isinstance(w.get("default_page_size"), int) and isinstance(w.get("max_page_size"), int)), None)
    default_limit = active_ws.get("default_page_size") if active_ws else 25
    max_page_size = active_ws.get("max_page_size") if active_ws else 200

    if limit is None:
        limit = default_limit
    if not isinstance(limit, int):
        return _err("VALIDATION_ERROR", "limit must be an integer.")
    if limit < 1 or limit > max_page_size:
        return _err("VALIDATION_ERROR", f"limit must be between 1 and {max_page_size}.")

    # filter
    rows = workspaces
    if status is not None:
        rows = [w for w in rows if w.get("status") == status]

    # stable sort
    def _key(w):
        return (w.get("created_at") or "", w.get("workspace_id") or "")
    rows_sorted = sorted(rows, key=_key)

    total = len(rows_sorted)
    page = rows_sorted[start_at:start_at + limit]
    has_more = (start_at + limit) < total
    next_cursor = (start_at + limit) if has_more else None

    # log request (no resolved workspace_id: store "unknown")
    tool_requests = _load("tool_requests.json")
    latency_ms = int((time.time() - t0) * 1000)
    tr_now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    tool_requests.append({
        "tool_request_id": "ais_trq_" + uuid.uuid4().hex[:26],
        "workspace_id": "unknown",
        "connection_id": None,
        "tool_name": "workspaces_list",
        "params_json": {"status": status, "limit": limit, "start_at": start_at},
        "status": "succeeded",
        "http_status": 200,
        "error_code": None,
        "error_message": None,
        "result_json": {"count": len(page)},
        "affected_entities": None,
        "started_at": tr_now,
        "finished_at": tr_now,
        "created_at": tr_now,
        "updated_at": tr_now,
        "latency_ms": latency_ms
    })
    _save("tool_requests.json", tool_requests)

    return {
        "workspaces": page,
        "pagination": {
            "total": total,
            "start_at": start_at,
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor
        }
    }

def atlassian_connections_create(workspace_id, product, deployment, base_url, auth_type, auth_principal, auth_secret, verify=None, **_extra):
    import json, os, datetime, time, uuid, re, urllib.parse
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0275000" if __import__("os").path.isdir("./environment_mix/0275000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    tool_name = "atlassian_connections_create"
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix): return f"{prefix}{uuid.uuid4().hex[:26].upper()}"

    def _append_tool_request(status, http_status=None, error_code=None, error_message=None, result_json=None, affected_entities=None, started_at=None, finished_at=None, conn_for_log=None):
        trs = _load("tool_requests.json")
        row = {
            "tool_request_id": _new_id("ais_trq_"),
            "workspace_id": workspace_id if isinstance(workspace_id, str) else "unknown",
            "connection_id": conn_for_log,
            "tool_name": tool_name,
            "params_json": {
                "workspace_id": workspace_id,
                "product": product,
                "deployment": deployment,
                "base_url": base_url,
                "auth_type": auth_type,
                "auth_principal": auth_principal,
                "verify": verify if verify is not None else True,
            },
            "status": status,
            "http_status": http_status,
            "error_code": error_code,
            "error_message": error_message,
            "result_json": result_json,
            "affected_entities": affected_entities,
            "started_at": started_at,
            "finished_at": finished_at,
            "created_at": now,
            "updated_at": now,
        }
        trs.append(row)
        _save("tool_requests.json", trs)
        return row

    # Validate inputs (accept vendor enums; map to internal where needed)
    if not isinstance(workspace_id, str) or not workspace_id:
        _append_tool_request("rejected", http_status=400, error_code="VALIDATION_ERROR", error_message="workspace_id must be a non-empty string.", started_at=now, finished_at=now)
        return _err("VALIDATION_ERROR", "workspace_id must be a non-empty string.", error_code="VALIDATION_ERROR")
    if product not in ("jira", "confluence"):
        _append_tool_request("rejected", http_status=400, error_code="VALIDATION_ERROR", error_message="product must be 'jira' or 'confluence'.", started_at=now, finished_at=now)
        return _err("VALIDATION_ERROR", "product must be 'jira' or 'confluence'.", error_code="VALIDATION_ERROR")

    # Vendor includes datacenter; internal schema uses server. Map datacenter -> server.
    if deployment not in ("cloud", "server", "datacenter"):
        _append_tool_request("rejected", http_status=400, error_code="VALIDATION_ERROR", error_message="deployment must be 'cloud', 'server', or 'datacenter'.", started_at=now, finished_at=now)
        return _err("VALIDATION_ERROR", "deployment must be 'cloud', 'server', or 'datacenter'.", error_code="VALIDATION_ERROR")
    deployment_mapped = "server" if deployment == "datacenter" else deployment

    if not isinstance(base_url, str) or not base_url:
        _append_tool_request("rejected", http_status=400, error_code="VALIDATION_ERROR", error_message="base_url must be a non-empty string.", started_at=now, finished_at=now)
        return _err("VALIDATION_ERROR", "base_url must be a non-empty string.", error_code="VALIDATION_ERROR")
    try:
        u = urllib.parse.urlparse(base_url)
        if u.scheme not in ("http", "https") or not u.netloc:
            raise ValueError("bad url")
    except Exception:
        _append_tool_request("rejected", http_status=400, error_code="VALIDATION_ERROR", error_message="base_url must be a valid URL string.", started_at=now, finished_at=now)
        return _err("VALIDATION_ERROR", "base_url must be a valid URL string.", error_code="VALIDATION_ERROR")

    if auth_type not in ("oauth2", "api_token", "personal_access_token"):
        _append_tool_request("rejected", http_status=400, error_code="VALIDATION_ERROR", error_message="auth_type must be 'oauth2', 'api_token', or 'personal_access_token'.", started_at=now, finished_at=now)
        return _err("VALIDATION_ERROR", "auth_type must be 'oauth2', 'api_token', or 'personal_access_token'.", error_code="VALIDATION_ERROR")
    if not isinstance(auth_principal, str) or not auth_principal:
        _append_tool_request("rejected", http_status=400, error_code="VALIDATION_ERROR", error_message="auth_principal must be a non-empty string.", started_at=now, finished_at=now)
        return _err("VALIDATION_ERROR", "auth_principal must be a non-empty string.", error_code="VALIDATION_ERROR")
    if not isinstance(auth_secret, str) or not auth_secret:
        _append_tool_request("rejected", http_status=400, error_code="VALIDATION_ERROR", error_message="auth_secret must be a non-empty string.", started_at=now, finished_at=now)
        return _err("VALIDATION_ERROR", "auth_secret must be a non-empty string.", error_code="VALIDATION_ERROR")
    if verify is None:
        verify = True
    if not isinstance(verify, bool):
        _append_tool_request("rejected", http_status=400, error_code="VALIDATION_ERROR", error_message="verify must be a boolean when provided.", started_at=now, finished_at=now)
        return _err("VALIDATION_ERROR", "verify must be a boolean when provided.", error_code="VALIDATION_ERROR")

    # Resolve workspace
    workspaces = _load("workspaces.json")
    ws = next((w for w in workspaces if w.get("workspace_id") == workspace_id), None)
    if not ws:
        _append_tool_request("failed", http_status=404, error_code="NOT_FOUND", error_message="Workspace not found.", started_at=now, finished_at=now)
        return _err("NOT_FOUND", "Workspace not found.", error_code="NOT_FOUND")
    if ws.get("status") != "active":
        _append_tool_request("rejected", http_status=403, error_code="WORKSPACE_INACTIVE", error_message="Workspace is not active.", started_at=now, finished_at=now)
        return _err("UNAUTHORIZED", "Workspace is not active.", error_code="WORKSPACE_INACTIVE")

    # Enforce unique(workspace_id, product)
    conns = _load("atlassian_connections.json")
    existing = next((c for c in conns if c.get("workspace_id") == workspace_id and c.get("product") == product), None)
    if existing and existing.get("status") != "deleted":
        _append_tool_request("failed", http_status=409, error_code="CONFLICT", error_message="Connection already exists for workspace and product.", started_at=now, finished_at=now, conn_for_log=existing.get("connection_id"))
        return _err("CONFLICT", "Connection already exists for workspace and product.", error_code="CONFLICT")

    # Map vendor auth_type to internal enum
    internal_auth_type = {"oauth2": "oauth", "api_token": "api_token", "personal_access_token": "pat"}[auth_type]

    # Create a secret reference (we don't store auth_secret itself in this datastore)
    secret_suffix = uuid.uuid4().hex[:16]
    auth_secret_ref = f"secret/atlassian/{workspace_id}/{product}/{secret_suffix}"
    if not re.match(r"^[A-Za-z0-9_./:-]+$", auth_secret_ref):
        _append_tool_request("failed", http_status=500, error_code="INVALID_JSON", error_message="Generated secret ref invalid.", started_at=now, finished_at=now)
        return _err("VALIDATION_ERROR", "Generated secret ref invalid.", error_code="INVALID_JSON")

    status = "active" if verify else "disabled"
    new_conn = {
        "connection_id": _new_id("ais_con_"),
        "workspace_id": workspace_id,
        "product": product,
        "deployment": deployment_mapped,
        "base_url": base_url,
        "auth_type": internal_auth_type,
        "auth_principal": auth_principal,
        "auth_secret_ref": auth_secret_ref,
        "status": status,
        "last_verified_at": now if verify else None,
        "last_sync_at": None,
        "created_at": now,
        "updated_at": now,
    }

    conns.append(new_conn)
    _save("atlassian_connections.json", conns)

    _append_tool_request(
        "succeeded",
        http_status=201,
        result_json=new_conn,
        affected_entities=None,
        started_at=now,
        finished_at=datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
        conn_for_log=new_conn.get("connection_id"),
    )
    return new_conn

def atlassian_connections_update(workspace_id, connection_id, base_url=None, auth_principal=None, auth_secret=None, status=None, verify=None, **_extra):
    import json, os, datetime, time, urllib.parse
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0275000" if __import__("os").path.isdir("./environment_mix/0275000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    # Validate required
    if not isinstance(workspace_id, str) or not workspace_id.strip():
        return _err("VALIDATION_ERROR", "workspace_id must be a non-empty string")
    if not isinstance(connection_id, str) or not connection_id.strip():
        return _err("VALIDATION_ERROR", "connection_id must be a non-empty string")

    # Validate optionals
    if base_url is not None:
        if not isinstance(base_url, str) or not base_url.strip():
            return _err("VALIDATION_ERROR", "base_url must be a non-empty string when provided")
        try:
            pu = urllib.parse.urlparse(base_url.strip())
        except Exception:
            pu = None
        if not pu or pu.scheme not in ("http", "https") or not pu.netloc:
            return _err("VALIDATION_ERROR", "base_url must be a valid URL string (http/https)")
    if auth_principal is not None and (not isinstance(auth_principal, str) or not auth_principal.strip()):
        return _err("VALIDATION_ERROR", "auth_principal must be a non-empty string when provided")
    if auth_secret is not None and (not isinstance(auth_secret, str) or not auth_secret.strip()):
        return _err("VALIDATION_ERROR", "auth_secret must be a non-empty string when provided")
    if status is not None and status not in ("active", "disabled", "error"):
        return _err("VALIDATION_ERROR", "status must be one of: active, disabled, error")
    if verify is None:
        verify = False
    if not isinstance(verify, bool):
        return _err("VALIDATION_ERROR", "verify must be a boolean")

    tool_requests = _load("tool_requests.json")
    workspaces = _load("workspaces.json")
    conns = _load("atlassian_connections.json")

    wsp = next((w for w in workspaces if w.get("workspace_id") == workspace_id), None)

    req_id = "ais_trq_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f")
    tr = {
        "tool_request_id": req_id,
        "workspace_id": workspace_id,
        "connection_id": connection_id,
        "tool_name": "atlassian_connections_update",
        "params_json": {
            "workspace_id": workspace_id,
            "connection_id": connection_id,
            **({} if base_url is None else {"base_url": base_url}),
            **({} if auth_principal is None else {"auth_principal": auth_principal}),
            **({"auth_secret_rotated": True} if auth_secret is not None else {}),
            **({} if status is None else {"status": status}),
            "verify": verify,
        },
        "status": "received",
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "result_json": None,
        "affected_entities": [],
        "started_at": now,
        "finished_at": None,
        "created_at": now,
        "updated_at": now,
    }

    if wsp is None:
        tr["status"] = "failed"
        tr["http_status"] = 404
        tr["error_code"] = "NOT_FOUND"
        tr["error_message"] = "Workspace not found"
        tr["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        tr["updated_at"] = tr["finished_at"]
        tool_requests.append(tr)
        _save("tool_requests.json", tool_requests)
        return _err("NOT_FOUND", "Workspace not found")

    if wsp.get("status") != "active":
        tr["status"] = "rejected"
        tr["http_status"] = 403
        tr["error_code"] = "WORKSPACE_INACTIVE"
        tr["error_message"] = "Workspace is not active"
        tr["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        tr["updated_at"] = tr["finished_at"]
        tool_requests.append(tr)
        _save("tool_requests.json", tool_requests)
        return _err("UNAUTHORIZED", "Workspace is not active", error_code="WORKSPACE_INACTIVE")

    idx = None
    for i, c in enumerate(conns):
        if c.get("connection_id") == connection_id and c.get("workspace_id") == workspace_id:
            idx = i
            break
    if idx is None:
        tr["status"] = "failed"
        tr["http_status"] = 404
        tr["error_code"] = "NOT_FOUND"
        tr["error_message"] = "Connection not found"
        tr["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        tr["updated_at"] = tr["finished_at"]
        tool_requests.append(tr)
        _save("tool_requests.json", tool_requests)
        return _err("NOT_FOUND", "Connection not found")

    conn = dict(conns[idx])  # work on copy
    prev_status = conn.get("status")

    # Apply updates
    changed = False
    if base_url is not None and base_url.strip() != conn.get("base_url"):
        conn["base_url"] = base_url.strip()
        changed = True
    if auth_principal is not None and auth_principal.strip() != (conn.get("auth_principal") or ""):
        conn["auth_principal"] = auth_principal.strip()
        changed = True
    if auth_secret is not None:
        # rotate secret ref (no plaintext stored)
        conn["auth_secret_ref"] = f"sec_{connection_id}_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S%f')}"
        changed = True

    # Optional set status (with verification constraint)
    if status is not None and status != prev_status:
        # Lifecycle transitions
        allowed = {
            "active": {"disabled", "error"},
            "error": {"active", "disabled"},
            "disabled": {"active"},
        }
        if prev_status not in allowed or status not in allowed[prev_status]:
            tr["status"] = "failed"
            tr["http_status"] = 409
            tr["error_code"] = "INVALID_TRANSITION"
            tr["error_message"] = "Illegal connection status transition"
            tr["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            tr["updated_at"] = tr["finished_at"]
            tool_requests.append(tr)
            _save("tool_requests.json", tool_requests)
            return _err("INVALID_TRANSITION", "Illegal connection status transition")
        conn["status"] = status
        changed = True

    # Verify (offline heuristic) after applying updates; if verify true, update status/last_verified_at.
    if verify:
        ok = True
        # If rotating secret, require length>=8 to "verify"
        if auth_secret is not None and len(auth_secret.strip()) < 8:
            ok = False
        # base_url validity already checked
        conn["last_verified_at"] = now
        if not ok:
            # refuse setting to active if verification fails
            if conn.get("status") == "active":
                tr["status"] = "failed"
                tr["http_status"] = 409
                tr["error_code"] = "UPSTREAM_UNAVAILABLE"
                tr["error_message"] = "Verification failed; cannot set status to active"
                tr["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                tr["updated_at"] = tr["finished_at"]
                tool_requests.append(tr)
                _save("tool_requests.json", tool_requests)
                return _err("CONFLICT", "Verification failed; cannot set status to active", error_code="UPSTREAM_UNAVAILABLE")
            # Otherwise mark error
            conn["status"] = "error"
            changed = True

    if not changed:
        # No success without effect: treat as NOT_FOUND-equivalent for mutation with no changes
        tr["status"] = "failed"
        tr["http_status"] = 404
        tr["error_code"] = "NOT_FOUND"
        tr["error_message"] = "No updates applied"
        tr["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        tr["updated_at"] = tr["finished_at"]
        tool_requests.append(tr)
        _save("tool_requests.json", tool_requests)
        return _err("NOT_FOUND", "No updates applied")

    conn["updated_at"] = now
    conns[idx] = conn
    _save("atlassian_connections.json", conns)

    tr["status"] = "succeeded"
    tr["http_status"] = 200
    tr["result_json"] = {"connection": conn}
    tr["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    tr["updated_at"] = tr["finished_at"]
    tool_requests.append(tr)
    _save("tool_requests.json", tool_requests)

    return {"connection": conn}

