            **({} if name is None else {"name": name}),
            **({} if read_only_mode is None else {"read_only_mode": read_only_mode}),
            **({} if default_page_size is None else {"default_page_size": default_page_size}),
            **({} if max_page_size is None else {"max_page_size": max_page_size}),
            **({} if status is None else {"status": status}),
        },
        "status": "received",
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "result_json": None,
        "affected_entities": [],
        "started_at": now,
        "finished_at": None,
        "created_at": now,
        "updated_at": now,
    }

    idx = None
    for i, w in enumerate(workspaces):
        if w.get("workspace_id") == workspace_id:
            idx = i
            break
    if idx is None:
        tr["status"] = "failed"
        tr["http_status"] = 404
        tr["error_code"] = "NOT_FOUND"
        tr["error_message"] = "Workspace not found"
        tr["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        tr["updated_at"] = tr["finished_at"]
        tool_requests.append(tr)
        _save("tool_requests.json", tool_requests)
        return _err("NOT_FOUND", "Workspace not found")

    wsp = dict(workspaces[idx])
    prev_status = wsp.get("status")

    # Cannot modify deleted workspace
    if prev_status == "deleted":
        tr["status"] = "failed"
        tr["http_status"] = 409
        tr["error_code"] = "INVALID_TRANSITION"
        tr["error_message"] = "Cannot modify a deleted workspace"
        tr["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        tr["updated_at"] = tr["finished_at"]
        tool_requests.append(tr)
        _save("tool_requests.json", tool_requests)
        return _err("INVALID_TRANSITION", "Cannot modify a deleted workspace")

    changed = False

    # unique(name)
    if name is not None:
        new_name = name.strip()
        if any((w.get("workspace_id") != workspace_id and (w.get("name") or "") == new_name) for w in workspaces):
            tr["status"] = "failed"
            tr["http_status"] = 409
            tr["error_code"] = "CONFLICT"
            tr["error_message"] = "Workspace name must be unique"
            tr["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            tr["updated_at"] = tr["finished_at"]
            tool_requests.append(tr)
            _save("tool_requests.json", tool_requests)
            return _err("CONFLICT", "Workspace name must be unique")
        if new_name != wsp.get("name"):
            wsp["name"] = new_name
            changed = True

    if read_only_mode is not None and read_only_mode != wsp.get("read_only_mode"):
        wsp["read_only_mode"] = read_only_mode
        changed = True

    # Apply pagination constraints with cross-field constraints
    new_default = wsp.get("default_page_size")
    new_max = wsp.get("max_page_size")

    if default_page_size is not None:
        new_default = default_page_size
    if max_page_size is not None:
        new_max = max_page_size

    if new_default is None or new_max is None:
        tr["status"] = "failed"
        tr["http_status"] = 400
        tr["error_code"] = "VALIDATION_ERROR"
        tr["error_message"] = "Workspace pagination settings are missing"
        tr["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        tr["updated_at"] = tr["finished_at"]
        tool_requests.append(tr)
        _save("tool_requests.json", tool_requests)
        return _err("VALIDATION_ERROR", "Workspace pagination settings are missing")

    if not isinstance(new_default, int) or new_default < 1:
        return _err("VALIDATION_ERROR", "default_page_size must be >= 1")
    if not isinstance(new_max, int) or new_max < 1 or new_max > 200:
        return _err("VALIDATION_ERROR", "max_page_size must be between 1 and 200")
    if new_default > new_max:
        return _err("VALIDATION_ERROR", "default_page_size must be <= max_page_size")

    if new_default != wsp.get("default_page_size"):
        wsp["default_page_size"] = new_default
        changed = True
    if new_max != wsp.get("max_page_size"):
        wsp["max_page_size"] = new_max
        changed = True

    # Lifecycle transition
    if status is not None and status != prev_status:
        allowed = {
            "active": {"suspended", "deleted"},
            "suspended": {"active", "deleted"},
            "deleted": set(),
        }
        if prev_status not in allowed or status not in allowed[prev_status]:
            tr["status"] = "failed"
            tr["http_status"] = 409
            tr["error_code"] = "INVALID_TRANSITION"
            tr["error_message"] = "Illegal workspace status transition"
            tr["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            tr["updated_at"] = tr["finished_at"]
            tool_requests.append(tr)
            _save("tool_requests.json", tool_requests)
            return _err("INVALID_TRANSITION", "Illegal workspace status transition")
        wsp["status"] = status
        changed = True

    if not changed:
        tr["status"] = "failed"
        tr["http_status"] = 404
        tr["error_code"] = "NOT_FOUND"
        tr["error_message"] = "No updates applied"
        tr["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        tr["updated_at"] = tr["finished_at"]
        tool_requests.append(tr)
        _save("tool_requests.json", tool_requests)
        return _err("NOT_FOUND", "No updates applied")

    wsp["updated_at"] = now
    workspaces[idx] = wsp
    _save("workspaces.json", workspaces)

    tr["status"] = "succeeded"
    tr["http_status"] = 200
    tr["result_json"] = {"workspace": wsp}
    tr["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    tr["updated_at"] = tr["finished_at"]
    tool_requests.append(tr)
    _save("tool_requests.json", tool_requests)

    return {"workspace": wsp}
